INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-GO-RDPR-2026-101', 'government_order', 'G.O. No. 101', 'Sixth State Finance Commission grants for 2026-27 to rural local bodies', NULL, 'Rural Development and Panchayat Raj Department', '2026-05-25', 'Sanctions and releases Rs.5,837,49,41,428 as Minimum Grant for 12,480 village panchayats and 388 panchayat unions for 10 months, and Population Grant for all three tiers of panchayats for 10 months (April 2026 to January 2027) under the Sixth State Finance Commission.', 'ஆறாவது மாநில நிதிக் குழுவின் கீழ் ஊரக உள்ளாட்சி அமைப்புகளுக்கு 2026 ஏப்ரல் முதல் 2027 ஜனவரி வரையிலான குறைந்தபட்ச மற்றும் மக்கள்தொகை அடிப்படையிலான மானியங்களை அனுமதிக்கும் அரசாணை.', FALSE, 'en', ARRAY['Rural local body funding']::text[], 'https://tnrd.tn.gov.in/latest_gos.php', 'https://tnrd.tn.gov.in/project/go_files/1_11_2026_101_en.pdf', '3f595f0269b3d4551f840528d90688527d590aa5252e28b47cc9d2b134cceac8', 9, NULL, 'official_verified', 'https://tnrd.tn.gov.in/project/go_files/1_11_2026_101_en.pdf', 'page-1 visual check of a scanned PDF', '2026-10-20', 'Scanned PDF (no text layer): page 1 was rendered and its title, number and date were checked by eye against this record on 2026-10-20.') ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-GO-RDPR-2026-89', 'government_order', 'G.O. No. 89', 'Pooled assigned revenue to rural local bodies for 2025-26', NULL, 'Rural Development and Panchayat Raj Department', '2026-03-27', 'Order sanctioning release of pooled assigned revenue to rural local bodies for 2025-26.', '2025-26 ஆம் ஆண்டுக்கான தொகுப்பு ஒதுக்கீட்டு வருவாயை ஊரக உள்ளாட்சி அமைப்புகளுக்கு விடுவிக்க அனுமதிக்கும் அரசாணை.', FALSE, 'en', ARRAY['Rural local body funding']::text[], 'https://tnrd.tn.gov.in/latest_gos.php', 'https://tnrd.tn.gov.in/project/go_files/1_13_2026_89_en.pdf', 'dcf6f037f3bcb19e36dc2501c5d26d02d5e296ee2ead31acdf0d8c8ad73ed239', 5, NULL, 'official_verified', 'https://tnrd.tn.gov.in/project/go_files/1_13_2026_89_en.pdf', 'page-1 visual check of a scanned PDF', '2026-10-20', 'Scanned PDF (no text layer): page 1 was rendered and its title, number and date were checked by eye against this record on 2026-10-20.') ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-GO-RDPR-2026-58', 'government_order', 'G.O. (Ms) No. 58', 'Creation of the new Kanjanur panchayat union (Villupuram) by restructuring Vikravandi and Kanai unions', NULL, 'Rural Development and Panchayat Raj Department', '2026-02-27', 'Order creating the new Kanjanur panchayat union in Villupuram district by restructuring the Vikravandi and Kanai panchayat unions, as titled on the department''s order list. The published PDF is in Tamil.', 'விழுப்புரம் மாவட்டத்தில் விக்கிரவாண்டி மற்றும் கானை ஊராட்சி ஒன்றியங்களை மறுசீரமைத்து புதிய கஞ்சனூர் ஊராட்சி ஒன்றியத்தை உருவாக்கும் அரசாணை. வெளியிடப்பட்ட PDF தமிழில் உள்ளது.', FALSE, 'ta', ARRAY['Panchayat administration']::text[], 'https://tnrd.tn.gov.in/latest_gos.php', 'https://tnrd.tn.gov.in/project/go_files/1_55_2026_58_ta.pdf', '06031a9af7c7a47f1e777a4b4181287973584d797abd34c070ffd57fbadbb25e', 15, NULL, 'official_verified', 'https://tnrd.tn.gov.in/project/go_files/1_55_2026_58_ta.pdf', 'page-1 visual check of a scanned PDF', '2026-10-20', 'Scanned PDF (no text layer): page 1 was rendered and its title, number and date were checked by eye against this record on 2026-10-20.') ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-GO-RDPR-2026-67', 'government_order', 'G.O. No. 67', 'Upgrading Karaikudi municipality to a corporation (merger of village panchayats)', NULL, 'Rural Development and Panchayat Raj Department', '2026-03-13', 'Order upgrading Karaikudi municipality to a corporation by merging five village panchayats of Sivaganga district (Kallal and Sakkottai panchayat unions), with a notification under section 15(4)(i) of the Tamil Nadu Panchayats Act, 1994. The published PDF is in Tamil.', 'காரைக்குடி நகராட்சியை மாநகராட்சியாக உயர்த்துவதையொட்டி சிவகங்கை மாவட்டத்தில் கிராம ஊராட்சிகளை மறுசீரமைக்கும் அரசாணை. வெளியிடப்பட்ட PDF தமிழில் உள்ளது.', FALSE, 'ta', ARRAY['Local body restructuring']::text[], 'https://tnrd.tn.gov.in/latest_gos.php', 'https://tnrd.tn.gov.in/project/go_files/1_55_2026_67_ta.pdf', '3d7a2a20fedc1d7ce17f9b124654ff57e7493d98b080bc9d4b5c849814cc146e', 8, NULL, 'official_verified', 'https://tnrd.tn.gov.in/project/go_files/1_55_2026_67_ta.pdf', 'page-1 visual check of a scanned PDF', '2026-10-20', 'Scanned PDF (no text layer): page 1 was rendered and its title, number and date were checked by eye against this record on 2026-10-20.') ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUD