INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-GO-MAWS-2023-3D-16', 'government_order', 'G.O. (3D) No. 16', 'Sanitation Workers Development Scheme guidelines', NULL, 'Municipal Administration and Water Supply Department', '2023-10-09', 'Implementation of the Sanitation Workers Development Scheme with technical support of the Urban Management Centre, Ahmedabad, for the welfare of sanitary workers - guidelines and sanction of a corpus fund (Municipal Administration and Water Supply, ME.2).', 'தூய்மைப் பணியாளர் மேம்பாட்டுத் திட்டத்தின் வழிகாட்டுதல்கள் (நகர்ப்புற உள்ளாட்சி அரசாணைப் பக்கத்தின் தலைப்பின்படி).', FALSE, 'en', ARRAY['Sanitation workers welfare']::text[], 'https://www.tnurbantree.tn.gov.in/government-orders/', 'https://www.tnurbantree.tn.gov.in/wp-content/uploads/2024/04/G.O3D.-No.16-dt.09.10.2023-5.pdf', 'f23f379d2d9ec51fb52925c40fb2b3b25cec29e2032112913c7e4fea7b8afe88', 46, NULL, 'official_verified', 'https://www.tnurbantree.tn.gov.in/wp-content/uploads/2024/04/G.O3D.-No.16-dt.09.10.2023-5.pdf', 'page-1 visual check of a scanned PDF', '2026-10-20', 'Scanned PDF (no text layer): page 1 was rendered and its title, number and date were checked by eye against this record on 2026-10-20.') ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-GO-MAWS-2023-45', 'government_order', 'G.O. (Ms) No. 45', 'Rules under the Tamil Nadu Urban Local Bodies Act, 1998 (as amended in 2022)', NULL, 'Municipal Administration and Water Supply (Election) Department', '2023-04-12', 'Issues the Tamil Nadu Urban Local Bodies Rules, 2023 under the Tamil Nadu Urban Local Bodies Act, 1998 (Tamil Nadu Act 9 of 1999) as updated by the Tamil Nadu Urban Local Bodies (Amendment) Act, 2022 (Tamil Nadu Act 35 of 2022).', '2022 இல் திருத்தப்பட்ட தமிழ்நாடு நகர்ப்புற உள்ளாட்சி அமைப்புகள் சட்டம், 1998 இன் கீழ் விதிகளை அறிவிக்கும் அரசாணை.', FALSE, 'en', ARRAY['Urban local bodies']::text[], 'https://www.tnurbantree.tn.gov.in/government-orders/', 'https://www.tnurbantree.tn.gov.in/wp-content/uploads/2023/07/GO-45-dated-12.04.23_0001-2.pdf', '53bf8c6a9020069cf96650bad6ed8865648431effae5613f9ccafde31002b160', 5, NULL, 'official_verified', 'https://www.tnurbantree.tn.gov.in/wp-content/uploads/2023/07/GO-45-dated-12.04.23_0001-2.pdf', 'page-1 visual check of a scanned PDF', '2026-10-20', 'Scanned PDF (no text layer): page 1 was rendered and its title, number and date were checked by eye against this record on 2026-10-20.') ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-GO-ADTW-2020-105', 'government_order', 'G.O. (Ms) No. 105', 'Increase in funeral rites assistance for Adi Dravidar and tribal families', NULL, 'Adi Dravidar and Tribal Welfare Department', '2020-10-19', 'Raises the assistance for funeral rites of deceased Adi Dravidar, tribal and Christian-convert Adi Dravidar persons from Rs.2,500 to Rs.5,000 and raises the annual family income ceiling for the assistance to Rs.72,000. The PDF is in Tamil and is listed on the Urban Local Bodies G.O. page.', 'ஆதிதிராவிடர், பழங்குடியினர் மற்றும் கிறித்துவ மதம் மாறிய ஆதிதிராவிடர் இனத்தவரின் ஈமச்சடங்கிற்கு வழங்கப்படும் தொகையை ரூ.2,500 இலிருந்து ரூ.5,000 ஆகவும், குடும்ப ஆண்டு வருமான வரம்பை ரூ.72,000 ஆகவும் உயர்த்தும் அரசாணை.', FALSE, 'ta', ARRAY['Funeral assistance']::text[], 'https://www.tnurbantree.tn.gov.in/government-orders/', 'https://www.tnurbantree.tn.gov.in/wp-content/uploads/2020/12/G.O.105-19-10-2020-Funeral-Rites-Grant-increased.pdf', '3d1049e7b96436e73e8dc0738c7c408f7c8045849d178f7080a0e41bdd3b1181', 3, NULL, 'official_verified', 'https://www.tnurbantree.tn.gov.in/wp-content/uploads/2020/12/G.O.105-19-10-2020-Funeral-Rites-Grant-increased.pdf', 'page-1 visual check of a scanned PDF', '2026-10-20', 'Scanned PDF (no text layer): page 1 was rendered and its title, number and date were checked by eye against this record on 2026-10-20.') ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-GO-SWWE-2025-64', 'government_order', 'G.O. (Ms) No. 64', 'Sexual Harassment of Women at Workplace (Prevention, Prohibition and Redressal) Act, 2013 - Standard Operating Procedure', NULL, 'Social Welfare and Women Empowerment Department', '2025-06-18', 'Approves the Standard Operating Procedure for implementing the Sexual Harassment of Women at Workplace (Prevention, Prohibition and Redressal) Act, 2013 (Central Act 14 of 2013) in Tamil Nadu. The PDF is hosted by the Directorate of Industrial Safety and Health.', 'பணியிடத்தில் பெண்களுக்கு எதிரான பாலியல் தொந்தரவு (தடுப்பு, தடை மற்றும் குறை தீர்வு) சட்டம், 2013 ஐ தமிழ்நாட்டில் செயல்படுத்துவதற்கான நிலையான செயல்பாட்டு நடைமுறையை அங்கீகரிக்கும் அரசாணை. PDF தொழில் பாதுகாப்பு மற்றும் சுகாதார இயக்ககத்தால் வழங்கப்படுகிறது.', FALSE, 'en', ARRAY['Women''s workplace safety']::text[], 'https://dish.tn.gov.in/', 'https://dish.tn.gov.in/assets/pdf/go/G.O.64.pdf', '5c969e408d201038881f3f3daf426b1c0928540fc8469e7bb148312c863b3bb4', 23, NULL, 'official_verified', 'https://dish.tn.gov.in/assets/pdf/go/G.O.64.pdf', 'page-1 visual check of a scanned PDF', '2026-10-20', 'Scanned PDF (no text layer): page 1 was rendered and its title, number and date were checked by eye against this record on 2026-10-20.') ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_ur