INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-POL-FOREST-2025-26', 'policy', 'Policy Note 2025-26', 'Forests Department - Policy Note 2025-26', NULL, 'Environment, Climate Change and Forests Department', NULL, 'Departmental policy note covering forest conservation, wildlife, forestry programmes and priorities for 2025-26.', '2025-26 ஆம் ஆண்டுக்கான வனப் பாதுகாப்பு, வனவிலங்கு, வனத் திட்டங்கள் மற்றும் துறை முன்னுரிமைகளை உள்ளடக்கிய கொள்கை விளக்கக் குறிப்பு.', FALSE, 'en', ARRAY['Forest conservation']::text[], 'https://www.forests.tn.gov.in/', 'https://www.forests.tn.gov.in/frontend/gos/Policy_Note_2025-260.pdf', '492d94eb4638afe2afc87992c8cbec22917489eada1b79304779bb4782e80f57', 245, NULL, 'official_verified', 'https://www.forests.tn.gov.in/frontend/gos/Policy_Note_2025-260.pdf', 'text match on the official PDF', '2026-10-20', 'Issue date not confirmed from the document text.') ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-POL-TNHB-2025-26', 'policy', 'Policy Note 2025-26', 'Housing and Urban Development - Policy Note 2025-26 (English)', NULL, 'Housing and Urban Development Department', NULL, 'Departmental policy note describing housing, urban development and related initiatives for 2025-26.', '2025-26 ஆம் ஆண்டுக்கான வீட்டுவசதி, நகர்ப்புற வளர்ச்சி மற்றும் தொடர்புடைய முன்முயற்சிகளை விவரிக்கும் கொள்கை விளக்கக் குறிப்பு.', FALSE, 'en', ARRAY['Housing']::text[], 'https://tnhb.tn.gov.in/', 'https://tnhb.tn.gov.in/assets/documents/Policy%20Note%20%26%20Announcements/English%20Policy%20Note%202025-2026.pdf', '71b46cf48b33b55466eab850c54985d227891d48305f846ee1df034d90b13180', 147, NULL, 'official_verified', 'https://tnhb.tn.gov.in/assets/documents/Policy%20Note%20%26%20Announcements/English%20Policy%20Note%202025-2026.pdf', 'text match on the official PDF', '2026-10-20', 'Issue date not confirmed from the document text.') ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-CIR-TNSJA-587', 'circular', 'R.O.C. No. 128404/2024/POCSO', 'Speedy disbursement of interim compensation to POCSO survivors', NULL, 'High Court of Madras / Tamil Nadu State Judicial Academy', '2025-12-08', 'Circular conveying the POCSO Committee''s direction to ensure speedy disbursement of interim compensation to survivors in POCSO Act cases.', 'போக்சோ வழக்குகளில் பாதிக்கப்பட்டவர்களுக்கு இடைக்கால இழப்பீட்டை விரைவாக வழங்க போக்சோ குழுவின் உத்தரவைத் தெரிவிக்கும் சுற்றறிக்கை.', FALSE, 'en', ARRAY['Victim compensation']::text[], 'https://tnsja.tn.gov.in/literature_IC.html', 'https://tnsja.tn.gov.in/impdec/587.pdf', '559e63a3d8d7937e0d1087e27c6e1de046332a141599db03c10c033e6187da50', 2, NULL, 'official_verified', 'https://tnsja.tn.gov.in/impdec/587.pdf', 'page-1 visual check of a scanned PDF', '2026-10-20', 'Scanned PDF (no text layer): page 1 was rendered and its title, number and date were checked by eye against this record on 2026-10-20.') ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EX