INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-CIR-TNSJA-595', 'circular', 'R.O.C. No. 3689-A/2026/F1', 'Directions regarding grant of maternity leave', NULL, 'High Court of Madras / Tamil Nadu State Judicial Academy', '2026-02-18', 'Circular communicating a High Court order (W.P. No. 705 of 2026) with directions on grant of maternity leave.', 'மகப்பேறு விடுப்பு வழங்குவது குறித்த உயர் நீதிமன்ற உத்தரவை (W.P. எண் 705/2026) தெரிவிக்கும் சுற்றறிக்கை.', FALSE, 'en', ARRAY['Maternity benefits']::text[], 'https://tnsja.tn.gov.in/literature_IC.html', 'https://tnsja.tn.gov.in/impdec/595.pdf', '466112de666625221782de09c159580cf8d26c86f4a8a1d8e4dfcc92c3cef71f', 11, NULL, 'official_verified', 'https://tnsja.tn.gov.in/impdec/595.pdf', 'page-1 visual check of a scanned PDF', '2026-10-20', 'Scanned PDF (no text layer): page 1 was rendered and its title, number and date were checked by eye against this record on 2026-10-20.') ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-CIR-TNSJA-594', 'circular', 'R.O.C. No. 15488-A/2026/F1', 'Ban on gutkha, pan masala and other chewing tobacco products - effective implementation', NULL, 'High Court of Madras / Tamil Nadu State Judicial Academy', '2026-02-18', 'Circular conveying High Court directions on effective implementation of the ban on gutkha, pan masala and tobacco/nicotine chewing products (Gazette Extraordinary Notification No. VI(1)/334(a)/2025 of 23.05.2025 prohibited their manufacture and sale for one year) and on prompt destruction of seized contraband.', 'குட்கா, பான் மசாலா மற்றும் புகையிலை/நிகோடின் மெல்லும் பொருட்கள் மீதான தடை அறிவிக்கையை திறம்பட செயல்படுத்துதல் மற்றும் பறிமுதல் பொருட்களை அகற்றுதல் குறித்த சுற்றறிக்கை.', FALSE, 'en', ARRAY['Public health']::text[], 'https://tnsja.tn.gov.in/literature_IC.html', 'https://tnsja.tn.gov.in/impdec/594.pdf', '18795da8aab1ac31ffa944daaae77808f55628361e13006be3b172d06b29028d', 3, NULL, 'official_verified', 'https://tnsja.tn.gov.in/impdec/594.pdf', 'page-1 visual check of a scanned PDF', '2026-10-20', 'Scanned PDF (no text layer): page 1 was rendered and its title, number and date were checked by eye against this record on 2026-10-20.') ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLU