INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-CIR-TNSJA-606', 'circular', 'R.O.C. No. 40578/2026/F1', 'Speedy day-to-day trial of bonded labour cases', NULL, 'High Court of Madras / Tamil Nadu State Judicial Academy', '2026-07-16', 'Circular concerning speedy day-to-day trial of bonded labour cases.', 'கொத்தடிமைத் தொழிலாளர் வழக்குகளை தினசரி விசாரணை முறையில் விரைவாக நடத்துவது குறித்த சுற்றறிக்கை.', FALSE, 'en', ARRAY['Labour welfare']::text[], 'https://tnsja.tn.gov.in/literature_IC.html', 'https://tnsja.tn.gov.in/impdec/606.pdf', '6be0bc0a3125ab4fa2926d919b71d9f2d44bbb6bdce77f1448f06c27db726938', 2, NULL, 'official_verified', 'https://tnsja.tn.gov.in/impdec/606.pdf', 'page-1 visual check of a scanned PDF', '2026-10-20', 'Scanned PDF (no text layer): page 1 was rendered and its title, number and date were checked by eye against this record on 2026-10-20.') ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-CIR-TNSJA-615', 'circular', 'R.O.C. No. 2760/R(DJ)/2026/F1', 'Guidelines for timely disbursement of Motor Vehicles Act compensation', NULL, 'High Court of Madras / Tamil Nadu State Judicial Academy', '2026-10-13', 'Circular directing strict compliance with High Court guidelines (C.M.A. No. 2064 of 2026) for protection and timely disbursement of compensation under the Motor Vehicles Act, 1988.', 'மோட்டார் வாகனச் சட்டம், 1988 இன் கீழ் இழப்பீட்டுத் தொகையை உரிய நேரத்தில் வழங்க உயர் நீதிமன்ற வழிகாட்டுதல்களை (C.M.A. எண் 2064/2026) கண்டிப்பாக பின்பற்றுமாறு கூறும் சுற்றறிக்கை.', FALSE, 'en', ARRAY['Accident compensation']::text[], 'https://tnsja.tn.gov.in/literature_IC.html', 'https://tnsja.tn.gov.in/impdec/615.pdf', '417c52ac6b9c198286df749e28e3e42985fb0c392a991b9fb3012ce00fd752e7', 4, NULL, 'official_verified', 'https://tnsja.tn.gov.in/impdec/615.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUD