INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-CIR-TNSJA-565', 'circular', 'R.O.C. No. 16380-A/2025/F1', 'Request from the Tamil Nadu State Legal Services Authority to Principal District Judges', NULL, 'High Court of Madras / Tamil Nadu State Judicial Academy', '2025-04-25', 'Circular forwarding a request from the Member Secretary, Tamil Nadu State Legal Services Authority, to the Principal District Judges.', 'தமிழ்நாடு மாநில சட்டப் பணிகள் ஆணையக் குழுவின் உறுப்பினர் செயலர் முதன்மை மாவட்ட நீதிபதிகளுக்கு விடுத்த கோரிக்கையை அனுப்பும் சுற்றறிக்கை.', FALSE, 'en', ARRAY['Legal aid']::text[], 'https://tnsja.tn.gov.in/literature_IC.html', 'https://tnsja.tn.gov.in/impdec/565.pdf', 'af842d2a39b3e5882c1025b9aa14f53fbb5e148a493bab240aba013309a203d1', 2, NULL, 'official_verified', 'https://tnsja.tn.gov.in/impdec/565.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-CIR-TNSJA-609', 'circular', 'R.O.C. No. 132011-A/2025/F1', 'Request from the State Human Rights Commission to Magistrates', NULL, 'High Court of Madras / Tamil Nadu State Judicial Academy', '2026-09-17', 'Circular forwarding a request from the Chairperson, State Human Rights Commission Tamil Nadu, to the Magistrates.', 'தமிழ்நாடு மாநில மனித உரிமைகள் ஆணையத் தலைவர் நீதித்துறை நடுவர்களுக்கு விடுத்த கோரிக்கையை அனுப்பும் சுற்றறிக்கை.', FALSE, 'en', ARRAY['Human rights']::text[], 'https://tnsja.tn.gov.in/literature_IC.html', 'https://tnsja.tn.gov.in/impdec/609.pdf', 'a27ef9ae7e951db13841b15bc010b76d3a9daffe49ebf55082c05152e27ee131', 2, NULL, 'official_verified', 'https://tnsja.tn.gov.in/impdec/609.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-CIR-TNSJA-589', 'circular', 'R.O.C. No. 129614-A/2025/F1', 'Recording statements of mentally or physically disabled victims in POCSO cases', NULL, 'High Court of Madras / Tamil Nadu State Judicial Academy', '2025-12-18', 'Circular issuing a Madurai Bench direction (H.C.P.(MD) No. 1331 of 2025): statements of temporarily or permanently, mentally or physically disabled victims are to be recorded under section 164(5-A) Cr.P.C. / 183(6) BNSS.', 'போக்சோ வழக்குகளில் மனநலம் அல்லது உடல் ஊனம் உள்ள பாதிக்கப்பட்டவர்களின் வாக்குமூலத்தை பிரிவு 164(5-A) Cr.P.C. / 183(6) BNSS இன் கீழ் பதிவு செய்யுமாறு மதுரைக் கிளை உத்தரவை (H.C.P.(MD) எண் 1331/2025) தெரிவிக்கும் சுற்றறிக்கை.', FALSE, 'en', ARRAY['Disability and victim support']::text[], 'https://tnsja.tn.gov.in/literature_IC.html', 'https://tnsja.tn.gov.in/impdec/589.pdf', '4756d2364a98ba25ecc8ea74fd2dbf0f3b244007f91c1439f8bc9d7ce3e153e0', 2, NULL, 'official_verified', 'https://tnsja.tn.gov.in/impdec/589.pdf', 'page-1 visual check of a scanned PDF', '2026-10-20', 'Scanned PDF (no text layer): page 1 was rendered and its title, number and date were checked by eye against this record on 2026-10-20.') ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-CIR-TNSJA-591', 'circular', 'R.O.C. No. 93246/2025/F1', 'Request from the Commissioner of Food Safety and Drug Administration on pending criminal cases', NULL, 'High Court of Madras / Tamil Nadu State Judicial Academy', '2026-01-02', 'Circular forwarding a requisition from the Commissioner, Tamil Nadu Food Safety and Drug Administration, to expedite disposal of pending criminal cases.', 'நிலுவையிலுள்ள குற்ற வழக்குகளை விரைவாக முடிக்க தமிழ்நாடு உணவுப் பாதுகாப்பு மற்றும் மருந்து நிர்வாக ஆணையரின் கோரிக்கையை அனுப்பும் சுற்றறிக்கை.', FALSE, 'en', ARRAY['Food safety']::text[], 'https://tnsja.tn.gov.in/literature_IC.html', 'https://tnsja.tn.gov.in/impdec/591.pdf', '5457197b1a4fa5d6a053fedd04142062b8ba18aa66bea1f5fe41dd86dab3797f', 2, NULL, 'official_verified', 'https://tnsja.tn.gov.in/impdec/591.pdf', 'page-1 visual check of a scanned PDF', '2026-10-20', 'Scanned PDF (no text layer): page 1 was rendered and its title, number and date were checked by eye against this record on 2026-10-20.') ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-NOT-GAZ-2026-436', 'notification', 'Notification No. II(1)/SWWE/22(a)/2026 (G.O.Ms. No. 29)', 'Mandatory use of Aadhaar number under section 7 of the Aadhaar Act, 2016', NULL, 'Social Welfare and Women Empowerment Department', '2026-10-06', 'Gazette notification on mandatory use of the Aadhaar number under section 7 of the Aadhaar Act, 2016 (G.O.Ms. No. 29, Social Welfare and Women Empowerment, 6 October 2026). The affected schemes are named in the notification itself.', 'ஆதார் சட்டம், 2016 பிரிவு 7 இன் கீழ் ஆதார் எண்ணைக் கட்டாயமாகப் பயன்படுத்துவது தொடர்பான அரசிதழ் அறிவிக்கை (அரசாணை (நிலை) எண் 29, 06.10.2026). பாதிக்கப்படும் திட்டங்கள் அறிவிக்கையிலேயே குறிப்பிடப்பட்டுள்ளன.', FALSE, 'en', ARRAY['Social welfare schemes']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/436_Ex_II_1_2026.pdf', '9d4169881e186ad425128193f53626eb261319f04fa02af532b77db482cd2cb3', 3, 'Published in the Tamil Nadu Government Gazette Extraordinary', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/436_Ex_II_1_2026.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-NOT-GAZ-2026-346', 'notification', 'Notification No. II(1)/AGFW/13(d)/2026 (G.O.Ms. No. 121)', 'Aadhaar authentication for beneficiaries of Price Deficiency Payment (PDP-MIS) for mango and Price Deficit Payment for oils', NULL, 'Agriculture - Farmers Welfare Department', '2026-08-11', 'Mandates Aadhaar authentication for beneficiaries of the Price Deficiency Payment under the Market Intervention Scheme for mango and the Price Deficit Payment Scheme for oils.', 'மாம்பழத்துக்கான சந்தைத் தலையீட்டுத் திட்ட விலைப் பற்றாக்குறை கொடுப்பனவு மற்றும் எண்ணெய்களுக்கான விலைப் பற்றாக்குறை கொடுப்பனவுத் திட்டப் பயனாளிகளுக்கு ஆதார் அங்கீகாரத்தைக் கட்டாயமாக்கும் அறிவிக்கை.', FALSE, 'en', ARRAY['Farmer price support']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/346_Ex_II_1_2026.pdf', 'da99bcab3c00c67a41c797250773f385cfeefb6e85b030ef676b9d34ada8f0f8', 5, 'Published in the Tamil Nadu Government Gazette Extraordinary', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/346_Ex_II_1_2026.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-NOT-GAZ-2026-311', 'notification', 'Notification No. II(1)/AGFW/10(b)/2026', 'Price Deficiency Payment under Market Intervention Scheme for Bangalora/Totapuri mango, 2026-2027 season', NULL, 'Agriculture - Farmers Welfare Department', '2026-07-15', 'Notification on implementing the Price Deficiency Payment under the Market Intervention Scheme for Bangalora/Totapuri mango in Tamil Nadu in the 2026-27 marketing season.', '2026-27 சந்தைப்படுத்தும் பருவத்தில் தமிழ்நாட்டில் பங்களோரா/தோதாபுரி மாம்பழத்துக்கான சந்தைத் தலையீட்டுத் திட்ட விலைப் பற்றாக்குறை கொடுப்பனவை செயல்படுத்தும் அறிவிக்கை.', FALSE, 'en', ARRAY['Farmer price support']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/311_Ex_II_1_2026.pdf', '74ef6b2e06524e136d951f8ee89a5e885a4207505a5abd4e50bb3563ddac2f25', 8, 'Published in the Tamil Nadu Government Gazette Extraordinary', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/311_Ex_II_1_2026.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-NOT-GAZ-2026-319', 'notification', 'Notification No. II(1)/FIN/10(d)/2026 (G.O.Ms. No. 139)', 'Constitution of the Seventh State Finance Commission', NULL, 'Finance Department', '2026-07-20', 'Constitutes the Seventh State Finance Commission to study the financial position of village panchayats, panchayat unions, district panchayats, town panchayats, municipalities and corporations.', 'கிராம ஊராட்சிகள், ஊராட்சி ஒன்றியங்கள், மாவட்ட ஊராட்சிகள், பேரூராட்சிகள், நகராட்சிகள் மற்றும் மாநகராட்சிகளின் நிதி நிலையை ஆய்வு செய்ய ஏழாவது மாநில நிதிக் குழுவை அமைக்கும் அறிவிக்கை.', FALSE, 'en', ARRAY['Local body finance']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/319_Ex_II_1_2026.pdf', 'd2f37ca4032f10b5997ae4cc75f773a740870e170db1491e6ad87d3c7498dbc7', 1, 'Published in the Tamil Nadu Government Gazette Extraordinary', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/319_Ex_II_1_2026.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-NOT-GAZ-2026-333', 'notification', 'Notification No. II(1)/MSME/13(b)/2026 (G.O.Ms. No. 18)', 'Aadhaar authentication of trainees in entrepreneurship development skill training programmes', NULL, 'Micro, Small and Medium Enterprises Department', '2026-07-30', 'Authorises Aadhaar authentication to establish the identity of trainees during registration, attendance marking and issue of certificates in skill training programmes.', 'திறன் பயிற்சித் திட்டங்களில் பதிவு, வருகைப் பதிவு மற்றும் சான்றிதழ் வழங்கும் போது பயிற்சியாளர்களின் அடையாளத்தை நிறுவ ஆதார் அங்கீகாரத்தை அனுமதிக்கும் அறிவிக்கை.', FALSE, 'en', ARRAY['Skill development']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/333_Ex_II_1_2026.pdf', '0d0dbe76d1eded1cf25205017fbb00363ef6451c6dd55da1ee0efcbebe1cc413', 2, 'Published in the Tamil Nadu Government Gazette Extraordinary', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/333_Ex_II_1_2026.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-NOT-GAZ-2026-341', 'notification', 'Notification No. II(2)/CTRRE/610(b)/2026 (G.O.Ms. No. 103)', 'Electronic presentation of instruments of first sale of plots and flats under the Registration Act, 1908 (amendment)', NULL, 'Commercial Taxes and Registration Department', '2026-08-06', 'Amends an earlier notification on presenting instruments of first sale of plots (promoters) and flats (builders) through electronic means under the Registration Act, 1908.', 'பதிவுச் சட்டம், 1908 இன் கீழ் மனை (மேம்பாட்டாளர்கள்) மற்றும் அடுக்குமாடி (கட்டுநர்கள்) முதல் விற்பனை ஆவணங்களை மின்னணு முறையில் சமர்ப்பிப்பது குறித்த முந்தைய அறிவிக்கையைத் திருத்தும் அறிவிக்கை.', FALSE, 'en', ARRAY['Property registration']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/341_Ex_II_2_2026.pdf', '392476c0f22e2bd2bd69e0476d909406248e9490bf98bdf6f0f6598d3ec64f5f', 1, 'Published in the Tamil Nadu Government Gazette Extraordinary', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/341_Ex_II_2_2026.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-NOT-GAZ-2026-338', 'notification', 'Notification No. SRO A-14(b)/2026 (G.O.Ms. No. 149)', 'Amendments to the Tamil Nadu change of land use (agriculture to non-agriculture, non-planning areas) Rules, 2017', NULL, 'Housing and Urban Development Department', '2026-07-31', 'Amends the rules governing change of land use from agricultural to non-agricultural purposes in non-planning areas.', 'திட்டமிடல் அல்லாத பகுதிகளில் விவசாய நிலத்தை விவசாயமல்லாத பயன்பாட்டிற்கு மாற்றுவதற்கான தமிழ்நாடு நில பயன்பாட்டு மாற்ற விதிகள், 2017 இல் திருத்தங்களை அறிவிக்கும் அறிவிக்கை.', FALSE, 'en', ARRAY['Land use']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/338_Ex_III_1a_2026.pdf', '8a68c4852c211f459fde11161ba9999ee504998c187835f49884bf1b42210857', 1, 'Published in the Tamil Nadu Government Gazette Extraordinary', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/338_Ex_III_1a_2026.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_r