INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-NOT-GAZ-2026-310', 'notification', 'Notification No. II(2)/HOU/544(b)/2026 (G.O.Ms. No. 145)', 'Supersession of the Tamil Nadu Real Estate Regulatory Authority', NULL, 'Housing and Urban Development Department', '2026-07-14', 'Supersedes the Tamil Nadu Real Estate Regulatory Authority and appoints persons to exercise its powers under the Real Estate (Regulation and Development) Act, 2016.', 'தமிழ்நாடு ரியல் எஸ்டேட் ஒழுங்குமுறை ஆணையத்தை நீக்கி, ரியல் எஸ்டேட் (ஒழுங்குமுறை மற்றும் மேம்பாடு) சட்டம், 2016 இன் கீழ் அதன் அதிகாரங்களைச் செயல்படுத்த நபர்களை நியமிக்கும் அறிவிக்கை.', FALSE, 'en', ARRAY['Real estate regulation']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/310_Ex_II_2_2026.pdf', '9e8727e8c0513ade3fb0f80b0b12ac69c2abd157e1d113fab53c98e74508a648', 1, 'Published in the Tamil Nadu Government Gazette Extraordinary', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/310_Ex_II_2_2026.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification