INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-NOT-GAZ-2026-415', 'notification', 'Notification No. II(2)/AGFW/726(a-1)/2026 (G.O.Ms. No. 150)', 'Date of coming into force of the Tamil Nadu Agricultural Produce Marketing (Regulation) Second Amendment Act, 2026 (Act 20 of 2026)', NULL, 'Agriculture - Farmers Welfare Department', '2026-09-25', 'Notifies the date of coming into force of Tamil Nadu Act 20 of 2026, the second amendment to the Agricultural Produce Marketing (Regulation) Act.', 'வேளாண் விளைபொருள் சந்தைப்படுத்தல் (ஒழுங்குமுறை) இரண்டாம் திருத்தச் சட்டம், 2026 (தமிழ்நாடு சட்டம் 20/2026) நடைமுறைக்கு வரும் தேதியை அறிவிக்கும் அறிவிக்கை.', FALSE, 'en', ARRAY['Agricultural marketing']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/415_Ex_II_2_2026.pdf', '7c412b84f06cf47c9b9d82450a513c015a04b786130a1ac080e1b8b04e50be04', 1, 'Published in the Tamil Nadu Government Gazette Extraordinary', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/415_Ex_II_2_2026.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_statu