INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-NOT-GAZ-2026-300', 'notification', 'Notification No. SRO A-12(g)/2026 (G.O.Ms. No. 129)', 'Amendments to the Tamil Nadu Combined Development and Building Rules, 2019', NULL, 'Housing and Urban Development Department', '2026-06-29', 'Amends the Tamil Nadu Combined Development and Building Rules, 2019.', 'தமிழ்நாடு ஒருங்கிணைந்த வளர்ச்சி மற்றும் கட்டிட விதிகள், 2019 இல் திருத்தங்களை அறிவிக்கும் அறிவிக்கை.', FALSE, 'en', ARRAY['Building regulation']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/300_Ex_III_1a_2026.pdf', '628e8f06db4bc169595b2283e3aeff73d4b7dee95d561b7e3ff016c30435da44', 1, 'Published in the Tamil Nadu Government Gazette Extraordinary', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/300_Ex_III_1a_2026.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLU