INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-ACT-TN-2026-1', 'act', 'Tamil Nadu Act 1 of 2026', 'An Act further to amend the Registration Act, 1908, in its application to the State of Tamil Nadu', NULL, 'Law Department', '2026-01-23', 'Amends the Registration Act, 1908 as applicable in Tamil Nadu. Published in the Extraordinary Gazette of 23 January 2026 (the issue PDF is dated 2025 in its file name).', 'தமிழ்நாட்டில் பொருந்தும் பதிவுச் சட்டம், 1908 ஐ மேலும் திருத்தும் சட்டம். 23 ஜனவரி 2026 சிறப்பு அரசிதழில் வெளியிடப்பட்டது.', FALSE, 'en', ARRAY['Property registration']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/30_Ex_IV_2_2025.pdf', 'a24284c5f943d3b7ba6f827dc0b3a3ecd4d9e920e638695d262f7ab20b2257a6', 2, 'Published as an Act in the Tamil Nadu Government Gazette Extraordinary (Part IV Section 2); commencement date not confirmed', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/30_Ex_IV_2_2025.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
