INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-ACT-TN-2026-10', 'act', 'Tamil Nadu Act 10 of 2026', 'The Tamil Nadu Prevention of Begging Amendment Act, 2026', NULL, 'Law Department', '2026-06-05', 'Amends provisions of the legislation concerning prevention of begging.', 'பிச்சை எடுப்பதைத் தடுக்கும் சட்டத்தின் விதிகளைத் திருத்தும் சட்டம்.', FALSE, 'en', ARRAY['Social welfare']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/274_Ex_IV_2_2026.pdf', '29dac4cb280cfd4742ac0a00d306524a6c93b76c8d464bc1315b64eee415d701', 12, 'Published as an Act in the Tamil Nadu Government Gazette Extraordinary (Part IV Section 2); commencement date not confirmed', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/274_Ex_IV_2_2026.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-ACT-TN-2026-11', 'act', 'Tamil Nadu Act 11 of 2026', 'The Tamil Nadu Co-operative Societies Amendment Act, 2024 (Act 11 of 2026)', NULL, 'Law Department', '2026-06-05', 'Amends the Tamil Nadu Co-operative Societies law. The Act carries the year 2024 in its short title but is numbered Act 11 of 2026 in the Gazette listing.', 'தமிழ்நாடு கூட்டுறவுச் சங்கங்கள் சட்டத்தைத் திருத்தும் சட்டம். சட்டத்தின் சுருக்கத் தலைப்பில் 2024 என்றிருந்தாலும், அரசிதழ் பட்டியலில் 2026 இன் சட்ட எண் 11 எனக் குறிக்கப்பட்டுள்ளது.', FALSE, 'en', ARRAY['Co-operatives']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/274_Ex_IV_2_2026.pdf', '29dac4cb280cfd4742ac0a00d306524a6c93b76c8d464bc1315b64eee415d701', 12, 'Published as an Act in the Tamil Nadu Government Gazette Extraordinary (Part IV Section 2); commencement date not confirmed', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/274_Ex_IV_2_2026.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-ACT-TN-2026-12', 'act', 'Tamil Nadu Act 12 of 2026', 'The Tamil Nadu Appointment on preferential basis in the Services under the State of Persons Studied in Tamil Medium (Amendment and Validation) Act, 2026', NULL, 'Law Department', '2026-08-11', 'Amends and validates the law on preferential appointment in state services of persons who studied in Tamil medium.', 'தமிழ் வழியில் படித்தவர்களுக்கு மாநிலப் பணிகளில் முன்னுரிமை நியமனம் தொடர்பான சட்டத்தைத் திருத்தி உறுதிப்படுத்தும் சட்டம்.', FALSE, 'en', ARRAY['Public employment']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/345_Ex_IV_2_2026.pdf', '014538e80d46b523969e0cfbed9b53a1204c61642671d92ccd94ed65434f8085', 2, 'Published as an Act in the Tamil Nadu Government Gazette Extraordinary (Part IV Section 2); commencement date not confirmed', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/345_Ex_IV_2_2026.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-ACT-TN-2026-14', 'act', 'Tamil Nadu Act 14 of 2026', 'The Tamil Nadu Town and Country Planning (Amendment) Act, 2026', NULL, 'Law Department', '2026-09-15', 'Amends the state''s town and country planning legislation.', 'மாநிலத்தின் நகர மற்றும் ஊரமைப்புச் சட்டத்தைத் திருத்தும் சட்டம்.', FALSE, 'en', ARRAY['Town planning']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/397_Ex_IV_2_2026.pdf', 'be8910699a427189e4f59eecfcb0376fabc4b5057a48017626a35f3c7fb510f9', 29, 'Published as an Act in the Tamil Nadu Government Gazette Extraordinary (Part IV Section 2); commencement date not confirmed', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/397_Ex_IV_2_2026.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-ACT-TN-2026-16', 'act', 'Tamil Nadu Act 16 of 2026', 'The Tamil Nadu Fire and Rescue Services (Amendment) Act, 2026', NULL, 'Law Department', '2026-09-15', 'Amends the Tamil Nadu Fire and Rescue Services legislation.', 'தமிழ்நாடு தீயணைப்பு மற்றும் மீட்புப் பணிகள் சட்டத்தைத் திருத்தும் சட்டம்.', FALSE, 'en', ARRAY['Public safety']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/397_Ex_IV_2_2026.pdf', 'be8910699a427189e4f59eecfcb0376fabc4b5057a48017626a35f3c7fb510f9', 29, 'Published as an Act in the Tamil Nadu Government Gazette Extraordinary (Part IV Section 2); commencement date not confirmed', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/397_Ex_IV_2_2026.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO documents.policy_document (doc_code, category, identifier, title, title_ta, issuing_authority, issued_on, summary_en, summary_ta, summary_ta_reviewed, language, related_topics, source_page_url, pdf_url, pdf_sha256, pdf_pages, legal_status, verification_status, source_document_ref, verification_method, last_checked_on, notes) VALUES ('DOC-ACT-TN-2026-21', 'act', 'Tamil Nadu Act 21 of 2026', 'The Tamil Nadu Public Service Commission (Additional Functions) Amendment Act, 2026', NULL, 'Law Department', '2026-09-15', 'Amends the law on additional functions of the Tamil Nadu Public Service Commission.', 'தமிழ்நாடு அரசுப் பணியாளர் தேர்வாணையத்தின் கூடுதல் பணிகள் தொடர்பான சட்டத்தைத் திருத்தும் சட்டம்.', FALSE, 'en', ARRAY['Public employment']::text[], 'https://stationeryprinting.tn.gov.in/extra_ordinary_lists.php?id=MjAyNg%3D%3D', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/397_Ex_IV_2_2026.pdf', 'be8910699a427189e4f59eecfcb0376fabc4b5057a48017626a35f3c7fb510f9', 29, 'Published as an Act in the Tamil Nadu Government Gazette Extraordinary (Part IV Section 2); commencement date not confirmed', 'official_verified', 'https://stationeryprinting.tn.gov.in/extraordinary/2026/397_Ex_IV_2_2026.pdf', 'text match on the official PDF', '2026-10-20', NULL) ON CONFLICT (doc_code) DO UPDATE SET category = EXCLUDED.category, identifier = EXCLUDED.identifier, title = EXCLUDED.title, issuing_authority = EXCLUDED.issuing_authority, issued_on = EXCLUDED.issued_on, summary_en = EXCLUDED.summary_en, summary_ta = EXCLUDED.summary_ta, language = EXCLUDED.language, related_topics = EXCLUDED.related_topics, source_page_url = EXCLUDED.source_page_url, pdf_url = EXCLUDED.pdf_url, pdf_sha256 = EXCLUDED.pdf_sha256, pdf_pages = EXCLUDED.pdf_pages, legal_status = EXCLUDED.legal_status, verification_status = EXCLUDED.verification_status, source_document_ref = EXCLUDED.source_document_ref, verification_method = EXCLUDED.verification_method, last_checked_on = EXCLUDED.last_checked_on, notes = EXCLUDED.notes;
INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-AMMA-BABY-CARE', 'Amma Baby Care Kit', 'அம்மா குழந்தை பராமரிப்பு பெட்டகம்', 'Supports newborn hygiene and early infant care after delivery in participating public healthcare facilities.', 'Provides baby-care and hygiene supplies to eligible mothers after childbirth. Distribution and kit contents depend on current programme instructions and the participating hospital.', 'அரசு மருத்துவமனைகளில் பிரசவித்த தகுதியுள்ள தாய்மார்களுக்கு குழந்தை பராமரிப்பு மற்றும் சுகாதாரப் பொருட்கள் வழங்கப்படுகின்றன.', 'state', 2, 'maternal_child_health', 'Baby-care and hygiene kit (contents depend on current programme instructions).', NULL, 'https://www.tnhealth.tn.gov.in', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Health and Family Welfare', 'Supports newborn hygiene and early infant care after delivery in participating public healthcare facilities.', '["Mother delivers at a participating Tamil Nadu government hospital or other eligible public facility, subject to current rules.", "Delivery and beneficiary details are recorded by the facility.", "Distribution may depend on local implementation and available stock."]'::jsonb, '[]'::jsonb, '["Ask the maternity ward or hospital help desk about current availability and eligibility.", "Provide the maternal-health or delivery details requested by the facility.", "Confirm the kit contents and collection procedure."]'::jsonb, 'Access is through the delivering government hospital; there is no separate application form.', '[{"url": "https://www.tnhealth.tn.gov.in", "label": "Health and Family Welfare Department"}]'::jsonb, '2026-10-20', 'Eligibility and kit contents are compiled from the project reference; the earlier ''16-item kit'' claim in the previous seed data has been removed because no official list was found.', '{}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
INSERT INTO schemes.benefit (scheme_id, benefit_type, description, amount, currency, frequency, conditions, amount_status) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-AMMA-BABY-CARE'), 'in_kind', 'Kit of infant-care and hygiene products; contents as per current programme arrangements.', NULL, 'INR', NULL, NULL, 'not_applicable');
INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-AMMA-BABY-CARE'), 'Mother-and-child health card or antenatal record', FALSE, 'if available', 'conditional');
INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-AMMA-BABY-CARE'), 'Hospital registration, delivery or newborn records', FALSE, NULL, 'unverified');
INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-AMMA-BABY-CARE'), 'Aadhaar or other identity proof', FALSE, 'if requested by the hospital', 'conditional');
INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-AMMA-UNAVAGAM', 'Amma Unavagam (Subsidized Canteens)', 'அம்மா உணவகம்', 'Provide affordable cooked food at designated public canteens.', 'A subsidised canteen service open to the general public, including daily-wage workers, commuters and low-income households. It is a service, not an individual cash-transfer scheme.', 'பொதுமக்களுக்கு, குறிப்பாக தினக்கூலி தொழிலாளர்களுக்கு, குறைந்த விலையில் சமைத்த உணவு வழங்கும் மானிய உணவக சேவை.', 'state', 7, 'food_security', 'Cooked meals at subsidised prices; check the posted menu and prices at the outlet.', NULL, 'https://www.tn.gov.in', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Municipal Administration and Urban Development / Urban Local Bodies', 'Provide affordable cooked food at designated public canteens.', '["Generally available to members of the public at operating outlets.", "No separate income-based beneficiary assessment is ordinarily required to buy a meal."]'::jsonb, '[]'::jsonb, '["Visit an operating Amma Unavagam outlet.", "Check the displayed menu, prices and operating hours."]'::jsonb, 'Walk-in service; no application.', '[{"url": "https://www.tn.gov.in", "label": "Government of Tamil Nadu portal"}]'::jsonb, '2026-10-20', 'The earlier seed listed fixed item prices (idli Rs.1 etc.); these could not be confirmed and are no longer shown.', '{}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
INSERT INTO schemes.benefit (scheme_id, benefit_type, description, amount, currency, frequency, conditions, amount_status) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-AMMA-UNAVAGAM'), 'in_kind', 'Cooked meals at subsidised prices. Current prices vary by outlet and must be checked locally.', NULL, 'INR', NULL, NULL, 'unverified');
INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-AMMA-UNAVAGAM'), 'No identity, income, ration-card or bank documents are ordinarily required to buy a meal', FALSE, 'per project reference; not confirmed by an official page', 'recommended');
INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-PATTA-CHITTA', 'Anytime Anywhere Land Records (e-Services)', 'நில ஆவண இணைய வழி சேவைகள் (பட்டா / சிட்டா)', 'Enable online access to eligible Tamil Nadu land-record information and related services.', 'The land-record portal gives access to records such as Patta, Chitta, A-Register and FMB where available. Viewing a record is different from applying to transfer or correct it; transaction requests need legal and administrative verification.', 'பட்டா, சிட்டா, அ-பதிவேடு, எஃப்.எம்.பி. போன்ற நில ஆவணத் தகவல்களை இணையத்தில் பார்க்க உதவும் சேவை.', 'state', 1, 'land_records', 'Online access to land-record details and extracts; fees for downloads are not confirmed.', 'https://eservices.tn.gov.in/', 'https://eservices.tn.gov.in/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_REVENUE'), 'Revenue and Disaster Management', 'Enable online access to eligible Tamil Nadu land-record information and related services.', '["People seeking information about land parcels recorded in Tamil Nadu.", "Applicants for changes or corrections must meet the requirements of the particular service."]'::jsonb, '[]'::jsonb, '["Open the official land-record e-services portal.", "Choose the required record or service and enter the requested land details.", "For transfer or correction, follow the portal or Revenue Department process and submit supporting records."]'::jsonb, NULL, '[{"url": "https://eservices.tn.gov.in/", "label": "TN e-Services portal"}]'::jsonb, '2026-10-20', 'The earlier seed stated ''Rs.50 for certified digital sign download''; this could not be confirmed and has been removed. The portal root page returned only a redirect on 2026-10-20.', '{}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
INSERT INTO schemes.benefit (scheme_id, benefit_type, description, amount, currency, frequency, conditions, amount_status) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-PATTA-CHITTA'), 'service', 'Online access to eligible land-record details and extracts.', NULL, 'INR', NULL, NULL, 'not_applicable');
INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-PATTA-CHITTA'), 'District, taluk, village, survey and subdivision details', TRUE, 'for a basic search, as requested by the portal', 'required');
INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-PATTA-CHITTA'), 'Existing patta and registered ownership documents', FALSE, 'for transfer or correction', 'conditional');
INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-PATTA-CHITTA'), 'Identity and contact details', FALSE, 'if required', 'conditional');
INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-CM-BREAKFAST', 'Chief Minister Breakfast Scheme', 'முதலமைச்சரின் காலை உணவுத் திட்டம்', 'Improve nutrition and school readiness for eligible primary-school children.', 'Provides breakfast to children in covered government primary schools on eligible school days, through the participating school rather than a separate cash-benefit application.', 'அரசு தொடக்கப் பள்ளிகளில் படிக்கும் குழந்தைகளுக்கு பள்ளி நாட்களில் காலை உணவு வழங்கும் திட்டம்.', 'state', 3, 'education_nutrition', 'Breakfast at no cost to the child on eligible school days.', NULL, 'https://www.tnschools.gov.in', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'School Education and implementing local authorities', 'Improve nutrition and school readiness for eligible primary-school children.', '["Children studying in Classes 1-5 at government schools covered by the programme.", "The school must be implementing the scheme."]'::jsonb, '[]'::jsonb, '["Ask the school headteacher whether the school is covered.", "The child receives breakfast through the school''s arrangements."]'::jsonb, 'Delivered through schools; there is no application.', '[{"url": "https://www.tnschools.gov.in", "label": "School Education Department"}]'::jsonb, '2026-10-20', 'School coverage and class range must be confirmed with the school.', '{}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
INSERT INTO schemes.benefit (scheme_id, benefit_type, description, amount, currency, frequency, conditions, amount_status) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-CM-BREAKFAST'), 'in_kind', 'Breakfast on eligible school days at no cost to the child.', NULL, 'INR', NULL, NULL, 'not_applicable');
INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-CM-BREAKFAST'), 'No separate scheme application is ordinarily required; school enrolment records establish student status', FALSE, 'per project reference', 'recommended');
INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-CM-HEALTH-INS', 'Chief Minister''s Comprehensive Health Insurance Scheme (CMCHIS)', 'முதலமைச்சரின் விரிவான மருத்துவக் காப்பீட்டுத் திட்டம்', 'Provide eligible families with financial protection for covered hospital treatment.', 'CMCHIS provides cashless treatment for approved procedures at empanelled hospitals, subject to eligibility, package limits and scheme rules.', 'தகுதியுள்ள குடும்பங்களுக்கு அங்கீகரிக்கப்பட்ட மருத்துவமனைகளில் பணமில்லா சிகிச்சை வழங்கும் மருத்துவக் காப்பீட்டுத் திட்டம்.', 'state', 2, 'health_insurance', 'Cashless treatment for covered procedures at empanelled hospitals. The cover (reported as Rs.5 lakh per family per year) and the income limit could not be confirmed from the official site.', 'https://www.cmchistn.com/', 'https://www.cmchistn.com/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Health and Family Welfare', 'Provide eligible families with financial protection for covered hospital treatment.', '["Tamil Nadu residence and family-card based enrolment.", "A family income ceiling applies; sources disagree (Rs.1,20,000 in most reports, Rs.72,000 on the national scheme portal). Check the official CMCHIS site.", "Eligible family members must meet enrolment requirements."]'::jsonb, '[]'::jsonb, '["Check eligibility on the official CMCHIS website.", "Visit the designated enrolment centre or use the applicable official process.", "Complete verification and keep the enrolment / card details.", "Before treatment, confirm the hospital is empanelled and the procedure is covered."]'::jsonb, NULL, '[{"url": "https://www.cmchistn.com/eligibility", "label": "CMCHIS eligibility page (content did not load without scripts on 2026-10-20)"}, {"url": "https://myscheme.gov.in/schemes/cmchis", "label": "National scheme portal listing (income limit differs)"}]'::jsonb, '2026-10-20', 'Conflicting income limits and a reported (unconfirmed) change in cover. Treat all figures as provisional.', '{}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
INSERT INTO schemes.benefit (scheme_id, benefit_type, description, amount, currency, frequency, conditions, amount_status) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-CM-HEALTH-INS'), 'insurance', 'Cashless treatment for covered procedures at empanelled hospitals; cover commonly reported as Rs.5 lakh per family per year.', 500000, 'INR', 'annual', 'Media reports in 2026 mention an announced increase to Rs.25 lakh; no confirmation that it is in force was found.', 'unverified');
INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-CM-HEALTH-INS'), 'Family / smart ration card', FALSE, NULL, 'unverified');
INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-CM-HEALTH-INS'), 'Income certificate', FALSE, 'where required', 'conditional');
INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-CM-HEALTH-INS'), 'Aadhaar and identity details of family members', FALSE, 'as required', 'conditional');
INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-CM-HEALTH-INS'), 'Residence and special-category documents', FALSE, NULL, 'category_specific');
INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-DISABILITY-PENSION', 'Differently Abled Pension Scheme (DAPS)', 'மாற்றுத்திறனாளிகள் ஓய்வூதியத் திட்டம்', 'Provide recurring financial assistance to eligible persons with disabilities who meet pension criteria.', 'A social-security pension for eligible people with disabilities facing financial hardship. DAPS is separate from the Indira Gandhi National Disability Pension Scheme (IGNDPS).', 'பொருளாதார நெருக்கடியில் உள்ள தகுதியுள்ள மாற்றுத்திறனாளிகளுக்கு மாதாந்திர ஓய்வூதியம் வழங்கும் திட்டம்.', 'state', 5, 'social_security', 'Monthly pension; Rs.1,500 per month was reported for differently abled pensions from 1 January 2023 (official page since unavailable).', 'https://www.tnesevai.tn.gov.in/', 'https://www.tnesevai.tn.gov.in/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_WELFARE'), 'Welfare of Differently Abled Persons / Revenue Administration', 'Provide recurring financial assistance to eligible persons with disabilities who meet pension criteria.', '["Tamil Nadu residence and other scheme conditions.", "Published district criteria mention benchmark disability of at least 40%; income, employment and destitution criteria may also apply.", "Confirm the current age, income and disability requirements with the district authority."]'::jsonb, '[]'::jsonb, '["Contact the Taluk Office, District Revenue Administration or an authorised e-Sevai centre.", "Submit the pension application with the documents.", "Complete eligibility verification and track the application."]'::jsonb, NULL, '[{"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "label": "e-Sevai Service List (updated 10/04/2023): DAPS, row 88"}, {"url": "https://oap.tn.gov.in/", "label": "Social security pensions portal"}]'::jsonb, '2026-10-20', 'Document list taken from the official e-Sevai service list (row 88); eligibility and amount remain provisional.', '{"documents": {"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "confirmed": true, "checked_on": "2026-10-20", "what": "e-Sevai list row 88"}}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
INSERT INTO schemes.benefit (scheme_id, benefit_type, description, amount, currency, frequency, conditions, amount_status) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-DISABILITY-PENSION'), 'pension', 'Monthly pension for differently abled persons.', 1500, 'INR', 'monthly', 'Rs.1,500 with effect from 01.01.2023 per the Commissionerate of Revenue Administration table (as of March 2024); the page returned 404 on 2026-10-20.', 'historical');
