INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-DISABILITY-PENSION'), 'Identity proof (Voter ID, passport, PAN, driving licence)', FALSE, 'optional per the e-Sevai list', 'recommended');
