INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-FREE-BUS-PASS', 'Vidiyal Payanam (Zero-Fare Bus Travel)', 'விடியல் பயணம் (கட்டணமில்லாப் பேருந்துப் பயணம்)', 'Reduce commuting costs for eligible passengers on designated ordinary government buses.', 'Eligible passengers travel without paying a fare on covered ordinary bus services. The benefit does not automatically apply to every premium, express or privately operated service.', 'தகுதியுள்ள பயணிகள் குறிப்பிட்ட சாதாரண அரசுப் பேருந்துகளில் கட்டணமின்றி பயணம் செய்யலாம்.', 'state', 14, 'transport_equity', 'Zero-fare travel on eligible ordinary government bus services.', NULL, 'https://mtcbus.tn.gov.in/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Transport Department / State Transport Undertakings', 'Reduce commuting costs for eligible passengers on designated ordinary government buses.', '["Women travelling on eligible ordinary buses.", "Transgender persons and persons with disabilities are included under applicable rules; confirm category conditions."]'::jsonb, '[]'::jsonb, '["Board an eligible ordinary government bus and follow the conductor''s ticketing procedure.", "Confirm the bus category and current rules with the transport undertaking."]'::jsonb, 'No application is needed.', '[{"url": "https://mtcbus.tn.gov.in/", "label": "Metropolitan Transport Corporation (Chennai)"}]'::jsonb, '2026-10-20', 'Applies to designated ordinary buses only.', '{}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
INSERT INTO schemes.benefit (scheme_id, benefit_type, description, amount, currency, frequency, conditions, amount_status) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-FREE-BUS-PASS'), 'in_kind', 'Zero-fare travel on eligible ordinary services.', NULL, 'INR', NULL, NULL, 'not_applicable');
INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-FREE-BUS-PASS'), 'No separate enrolment or income certificate is ordinarily needed for eligible women', FALSE, 'per project reference', 'recommended');
INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-FREE-BUS-PASS'), 'Special-category identification', FALSE, 'may be requested', 'category_specific');
INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-KALAIGNAR-MAGALIR-URIMAI', 'Kalaignar Magalir Urimai Thogai', 'கலைஞர் மகளிர் உரிமைத் தொகை', 'Provide monthly financial assistance to eligible women who head their households.', 'Recurring assistance to eligible women to help with household expenditure and strengthen financial independence.', 'குடும்பத் தலைவியாக உள்ள தகுதியுள்ள பெண்களுக்கு மாதாந்திர நிதி உதவி வழங்கும் திட்டம்.', 'state', 5, 'women_empowerment', 'Rs.1,000 per month was reported at launch (2023); check the current amount.', NULL, 'https://www.socialwelfare.tn.gov.in', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_WELFARE'), 'Tamil Nadu Government / designated implementing department', 'Provide monthly financial assistance to eligible women who head their households.', '["Woman aged 21 or above (born before 15 September 2002, as reported at launch); one woman per ration card.", "Annual family income below Rs.2.5 lakh; land up to 5 acres wetland or 10 acres dryland; household electricity use below 3,600 units a year (all as reported at launch in 2023).", "These criteria come from 2023 news reports, not an official page, and may have changed."]'::jsonb, '["As reported at launch: state / central government and PSU employees, bank employees, income-tax and professional-tax payers, pensioners, elected representatives of local bodies and owners of four-wheelers."]'::jsonb, '["Check whether registration or an application window is open.", "Use the designated registration camp or authorised channel.", "Submit household, identity and bank details and complete verification."]'::jsonb, NULL, '[{"url": "https://www.thenewsminute.com/article/tn-govt-announces-eligibility-criteria-monthly-financial-assistance-scheme-179471", "label": "News report of the launch criteria (secondary source)"}]'::jsonb, '2026-10-20', 'No official page confirming the current criteria was found; eligibility and amount are provisional.', '{}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
