INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-MAKKALAI-THEDI', 'Makkalai Thedi Maruthuvam', 'மக்களைத் தேடி மருத்துவம்', 'Deliver community and doorstep screening, follow-up and medicines for eligible patients.', 'Focuses on non-communicable diseases such as hypertension and diabetes. Health workers screen residents, support follow-up and deliver prescribed medicines where eligible.', 'உயர் இரத்த அழுத்தம், நீரிழிவு போன்ற நோய்களுக்கு வீடு தேடி பரிசோதனை, தொடர் சிகிச்சை மற்றும் மருந்துகள் வழங்கும் திட்டம்.', 'state', 2, 'public_health', 'Screening, follow-up and delivery of prescribed medicines at the doorstep.', NULL, 'https://tnhsp.org/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Health and Family Welfare', 'Deliver community and doorstep screening, follow-up and medicines for eligible patients.', '["Residents in covered areas who qualify for programme services.", "People needing screening or follow-up for hypertension, diabetes or other conditions covered by local protocols."]'::jsonb, '[]'::jsonb, '["Contact the local Primary Health Centre, Village Health Nurse or community health worker.", "Ask about local screening and home-visit services."]'::jsonb, 'Access is through the local health worker; there is no application form.', '[{"url": "https://tnhsp.org/", "label": "Tamil Nadu Health Systems Project"}]'::jsonb, '2026-10-20', 'Local availability varies.', '{}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
