INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-MOOVALUR-RAMAMIRTHAM', 'Pudhumai Penn (Moovalur Ramamirtham Ammaiyar Higher Education Assurance Scheme)', 'புதுமைப் பெண் திட்டம் (மூவலூர் இராமாமிர்தம் அம்மையார் உயர்கல்வி உறுதித் திட்டம்)', 'Encourage eligible girls to continue into higher education.', 'Monthly financial assistance to eligible girl students from the prescribed school background who continue into recognised higher education.', 'அரசுப் பள்ளிகளில் படித்து உயர்கல்வி தொடரும் மாணவிகளுக்கு மாதாந்திர உதவித்தொகை வழங்கும் திட்டம்.', 'state', 5, 'education_women', 'Rs.1,000 per month was reported for eligible students; check the current rules.', NULL, 'https://www.socialwelfare.tn.gov.in', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_WELFARE'), 'Social Welfare and Women Empowerment', 'Encourage eligible girls to continue into higher education.', '["Girl student who studied Classes 6-12 in Tamil Nadu government schools (as reported; verify any expansion).", "Enrolled in an eligible higher-education course and verified by the institution.", "Not applicable to distance / open-university courses (secondary report)."]'::jsonb, '[]'::jsonb, '["Contact the college scholarship / student-welfare office.", "Use the prescribed Penkalvi / UMIS or institutional workflow.", "Submit school-history, admission and bank details and track verification."]'::jsonb, NULL, '[{"url": "https://en.vikaspedia.in/schemesall/state-specific-schemes/tamil-nadu/pudhumai-pen-scheme", "label": "Vikaspedia summary (secondary source)"}]'::jsonb, '2026-10-20', 'The student-portal address in the project reference was malformed (''um is.tn.gov.in'') and is not used.', '{}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
