INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-NIRP-PENSION', 'Indira Gandhi National Old Age Pension Scheme (IGNOAPS / OAP)', 'இந்திரா காந்தி தேசிய முதியோர் ஓய்வூதியத் திட்டம்', 'Provide financial support to eligible destitute elderly people.', 'The old-age pension component of the National Social Assistance Programme, administered through Tamil Nadu''s social-security pension system.', 'ஆதரவற்ற மூத்த குடிமக்களுக்கு மாதாந்திர ஓய்வூதியம் வழங்கும் திட்டம்.', 'state', 1, 'social_security', 'Monthly pension; a total of Rs.1,200 per month was listed (central + state share) on the Revenue Administration table as of March 2024.', 'https://oap.tn.gov.in/', 'https://oap.tn.gov.in/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_REVENUE'), 'Revenue Administration and Disaster Management', 'Provide financial support to eligible destitute elderly people.', '["Generally at least 60 years of age.", "Must satisfy destitution, poverty, residence and verification criteria.", "Additional state-administered conditions may apply."]'::jsonb, '[]'::jsonb, '["Contact the Taluk Office, Revenue Department or an authorised e-Sevai centre.", "Submit the prescribed application and supporting records.", "Complete age, residence and financial-status verification."]'::jsonb, NULL, '[{"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "label": "e-Sevai Service List: IGNOAPS, row 83"}, {"url": "https://oap.tn.gov.in/", "label": "Social security pensions portal"}]'::jsonb, '2026-10-20', 'Document list is from the official e-Sevai service list; amount is historical until the current order is confirmed.', '{"documents": {"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "confirmed": true, "checked_on": "2026-10-20", "what": "e-Sevai list row 83"}}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
