INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-PM-KISAN', 'Pradhan Mantri Kisan Samman Nidhi (PM-KISAN)', 'பிரதம மந்திரி கிசான் சம்மான் நிதி (மத்திய அரசுத் திட்டம்)', 'Provide income support to eligible landholding farmer families.', 'A centrally funded direct-benefit scheme. Eligible farmer families receive instalments after land-record, identity and beneficiary verification. For the scheme a family means husband, wife and minor children.', 'நிலம் வைத்துள்ள தகுதியுள்ள விவசாயக் குடும்பங்களுக்கு ஆண்டுக்கு மூன்று தவணைகளாக நேரடி வருமான உதவி வழங்கும் மத்திய அரசுத் திட்டம்.', 'central', 4, 'agriculture_support', 'Rs.6,000 per year in three equal instalments, paid directly to the bank account.', 'https://pmkisan.gov.in/', 'https://pmkisan.gov.in/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Department of Agriculture and Farmers Welfare, Government of India; implemented with state verification', 'Provide income support to eligible landholding farmer families.', '["All landholding farmer families, as identified under the scheme guidelines (family = husband, wife and minor children).", "Land and beneficiary records must be verified; e-KYC is required for registered beneficiaries (project reference)."]'::jsonb, '["All institutional landholders.", "Former and present holders of constitutional posts; ministers, MPs, MLAs, MLCs, mayors of municipal corporations and chairpersons of district panchayats.", "Serving or retired officers and employees of central / state governments, PSEs and local bodies (excluding multi-tasking / Class IV / Group D staff).", "Retired pensioners with a monthly pension of Rs.10,000 or more (excluding multi-tasking / Class IV / Group D staff).", "Persons who paid income tax in the last assessment year.", "Professionals such as doctors, engineers, lawyers, chartered accountants and architects registered with professional bodies and practising."]'::jsonb, '["Use the official PM-KISAN portal and choose New Farmer Registration.", "Complete Aadhaar authentication and give the requested land and bank details.", "Complete e-KYC and check beneficiary status."]'::jsonb, NULL, '[{"url": "https://pmkisan.gov.in/", "label": "PM-KISAN portal"}]'::jsonb, '2026-10-20', 'Benefit amount, family definition and exclusions were read on the official PM-KISAN page; documents and steps are from the project reference.', '{"benefit": {"url": "https://pmkisan.gov.in/", "confirmed": true, "checked_on": "2026-10-20", "what": "Rs.6,000 / year in 3 equal instalments"}, "exclusions": {"url": "https://pmkisan.gov.in/", "confirmed": true, "checked_on": "2026-10-20", "what": "exclusion categories listed on the portal"}, "eligibility": {"url": "https://pmkisan.gov.in/", "confirmed": true, "checked_on": "2026-10-20", "what": "family definition"}}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
