INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-TAMIL-PUDHALVAN', 'Tamil Pudhalvan Scheme', 'தமிழ்ப் புதல்வன் திட்டம்', 'Support eligible male students continuing higher education after school.', 'Monthly assistance to eligible male students who meet the prescribed school-background and higher-education conditions.', 'அரசுப் பள்ளிகளில் படித்து உயர்கல்வி தொடரும் மாணவர்களுக்கு மாதாந்திர உதவித்தொகை வழங்கும் திட்டம்.', 'state', 3, 'education', 'Rs.1,000 per month was reported for eligible students; check the current order.', NULL, 'https://naanmudhalvan.tn.gov.in/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Special Programme Implementation / Higher Education implementation', 'Support eligible male students continuing higher education after school.', '["Male student in an eligible higher-education course.", "Must meet the prescribed Classes 6-12 school-background criteria; descriptions differ on government-aided and Tamil-medium schools, so verify the latest order.", "Institutional verification is required."]'::jsonb, '[]'::jsonb, '["Contact the college scholarship / student-welfare office.", "Use the prescribed UMIS / student application process.", "Submit records and track institutional verification."]'::jsonb, NULL, '[{"url": "https://karunya.edu/sites/default/files/img/Scholarship/TAMIL-PUDHALVAN.pdf", "label": "University scholarship notice (secondary source)"}]'::jsonb, '2026-10-20', 'The project reference points to the Naan Mudhalvan portal, whose root now redirects to skilldevelopment.tn.gov.in; no scheme page was confirmed.', '{}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
