INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-NAAN-MUDHALVAN', 'Naan Mudhalvan', 'நான் முதல்வன்', 'Improve employability through industry-relevant skills, training and career-development opportunities.', 'A state skills initiative offering eligible learners courses and career opportunities. Individual programmes have their own selection and eligibility rules.', 'மாணவர்களுக்கு தொழில்துறைக்கு ஏற்ற திறன் பயிற்சி மற்றும் வேலைவாய்ப்பு வாய்ப்புகளை வழங்கும் மாநில திறன் மேம்பாட்டு முயற்சி.', 'state', 9, 'skill_development', 'Skill courses, certification and career preparation; specific opportunities vary by programme.', 'https://naanmudhalvan.tn.gov.in/', 'https://naanmudhalvan.tn.gov.in/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Special Programme Implementation Department / Tamil Nadu Skill Development Corporation', 'Improve employability through industry-relevant skills, training and career-development opportunities.', '["Students and learners eligible for the particular course or opportunity.", "Institutional nomination, academic status or separate registration may be required for some programmes."]'::jsonb, '[]'::jsonb, '["Visit the official portal.", "Choose a course or opportunity and register.", "Complete institutional verification and any separate selection process."]'::jsonb, NULL, '[{"url": "https://naanmudhalvan.tn.gov.in/", "label": "Naan Mudhalvan portal (redirects to skilldevelopment.tn.gov.in)"}]'::jsonb, '2026-10-20', 'Portal reachable (redirect) on 2026-10-20; scheme details are from the project reference.', '{}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
