INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-CM-GIRL-CHILD', 'Chief Minister''s Girl Child Protection Scheme', 'முதலமைச்சரின் பெண் குழந்தை பாதுகாப்புத் திட்டம்', 'Promote girl-child welfare, education and long-term financial security.', 'A long-term deposit for eligible girl children in qualifying families; scheme categories and application timing follow detailed eligibility rules.', 'தகுதியுள்ள குடும்பங்களின் பெண் குழந்தைகளுக்கு நீண்டகால வைப்புத் தொகை வழங்கும் திட்டம்.', 'state', 5, 'women_child', 'Long-term deposit for an eligible girl child; amounts below are historical.', NULL, 'https://www.socialwelfare.tn.gov.in', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_WELFARE'), 'Social Welfare and Women Empowerment', 'Promote girl-child welfare, education and long-term financial security.', '["Tamil Nadu families meeting residence and income criteria.", "Scheme I generally covers one eligible girl child and Scheme II two eligible girl children, with no male child and other prescribed conditions.", "Age, parental sterilisation and application-timing conditions may apply."]'::jsonb, '[]'::jsonb, '["Contact the local Social Welfare Office or authorised e-Sevai centre.", "Confirm current eligibility and whether applications are open.", "Submit family, income and child records for verification."]'::jsonb, NULL, '[]'::jsonb, '2026-10-20', 'Amounts are historical and unverified.', '{}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
