INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-KANAVU-ILLAM', 'Kalaignarin Kanavu Illam', 'கலைஞரின் கனவு இல்லம்', 'Replace eligible rural huts with permanent houses.', 'A rural housing initiative to improve housing safety and move towards hut-free villages; selection depends on the applicable survey, beneficiary lists and annual implementation orders.', 'கிராமப்புறங்களில் குடிசை வீடுகளை நிரந்தர வீடுகளாக மாற்றும் வீட்டுவசதித் திட்டம்.', 'state', 8, 'housing', 'Financial assistance to build a permanent house at the current unit cost set by the implementation order.', NULL, 'https://www.tnrd.tn.gov.in/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_RDPR'), 'Rural Development and Panchayat Raj', 'Replace eligible rural huts with permanent houses.', '["Rural households identified as eligible through prescribed surveys or housing databases.", "House-site ownership / patta and other land conditions apply, subject to permitted exceptions.", "Households must meet current selection and exclusion criteria."]'::jsonb, '[]'::jsonb, '["Contact the Village Panchayat or Block Development Office.", "Check the eligible survey / beneficiary list.", "Submit or update household and land records.", "Complete local verification and follow the approved construction and payment procedures."]'::jsonb, NULL, '[{"url": "https://tnrd.tn.gov.in/latest_gos.php", "label": "Rural Development G.O. list"}]'::jsonb, '2026-10-20', 'Check the current-year order for the unit cost.', '{}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
