INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-EVR-MANIAMMAIYAR', 'E.V.R. Maniammaiyar Marriage Assistance Scheme for Daughters of Poor Widows', 'ஈ.வெ.ரா. மணியம்மையார் நினைவு ஏழை விதவையர் மகள் திருமண நிதியுதவித் திட்டம்', 'Reduce marriage-related financial burden for eligible daughters of poor widows.', 'A targeted assistance category that has historically given financial and gold-coin assistance to qualifying families. Current operational status and amounts require confirmation.', 'ஏழை விதவையரின் மகள்களின் திருமணச் செலவுக்கு நிதி மற்றும் தங்க நாணயம் வழங்கும் திட்டம் (தற்போதைய நிலை உறுதிப்படுத்தப்படவில்லை).', 'state', 5, 'marriage_assistance', 'Historical amounts only; current availability not confirmed.', NULL, 'https://www.tnesevai.tn.gov.in/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_WELFARE'), 'Social Welfare and Women Empowerment', 'Reduce marriage-related financial burden for eligible daughters of poor widows.', '["Bride belongs to an eligible widow-headed family.", "Age, income, residence and marriage conditions apply.", "Educational qualification may decide the assistance category."]'::jsonb, '[]'::jsonb, '["Contact the District Social Welfare Office or an authorised e-Sevai centre.", "Confirm the current scheme status and category.", "Submit the prescribed application and supporting records.", "Complete verification and track the decision."]'::jsonb, NULL, '[{"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "label": "e-Sevai Service List: SWL-107 listed (no fee / documents given)"}]'::jsonb, '2026-10-20', 'Listed on the e-Sevai service list as SWL-107; amounts are historical and unverified.', '{"listed": {"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "confirmed": true, "checked_on": "2026-10-20", "what": "SWL-107 listed"}}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
