INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-ANNAI-TERESA', 'Annai Teresa Ninaivu Marriage Assistance Scheme for Orphan Girls', 'அன்னை தெரசா நினைவு ஆதரவற்ற பெண்கள் திருமண நிதியுதவித் திட்டம்', 'Support eligible orphan girls with marriage-related financial assistance.', 'Historically intended to support eligible orphan girls without parental financial support. Current application status and benefits need departmental confirmation.', 'ஆதரவற்ற பெண்களின் திருமணச் செலவுக்கு நிதியுதவி வழங்கும் திட்டம் (தற்போதைய நிலை உறுதிப்படுத்தப்படவில்லை).', 'state', 5, 'marriage_assistance', 'Historical amounts only; current availability not confirmed.', NULL, 'https://www.tnesevai.tn.gov.in/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_WELFARE'), 'Social Welfare and Women Empowerment', 'Support eligible orphan girls with marriage-related financial assistance.', '["Applicant meets the scheme''s definition of an orphan girl.", "Age, residence and marriage requirements apply.", "Education may decide the assistance category."]'::jsonb, '[]'::jsonb, '["Contact the District Social Welfare Office or an authorised e-Sevai centre.", "Confirm the current operational status.", "Submit the prescribed application and documents for verification."]'::jsonb, NULL, '[{"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "label": "e-Sevai Service List: SWL-104 listed"}]'::jsonb, '2026-10-20', 'Listed as SWL-104; amounts historical and unverified.', '{"listed": {"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "confirmed": true, "checked_on": "2026-10-20", "what": "SWL-104 listed"}}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
