INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-MARRIAGE-DIFF-ABLED', 'Marriage Assistance for Differently Abled Persons', 'மாற்றுத்திறனாளிகள் திருமண நிதியுதவித் திட்டம்', 'Provide marriage-related assistance to eligible persons with disabilities and qualifying couples.', 'Assistance is given in defined categories (for example a person without disability marrying a visually impaired, orthopaedically differently abled or speech and hearing impaired person, or two differently abled persons). The benefit depends on the category and on degree or diploma qualifications. The project reference lists this scheme twice (entries 19 and 30); both are merged here.', 'மாற்றுத்திறனாளிகளின் திருமணத்திற்கு வகைப்பாட்டின்படி நிதி மற்றும் தங்க நாணயம் வழங்கும் திட்டம்.', 'state', NULL, 'marriage_assistance', 'Rs.25,000 (Rs.50,000 where either partner holds a degree or diploma) plus an 8-gram gold coin, as published by the Commissionerate (from 23.05.2016).', NULL, 'https://www.scd.tn.gov.in/marg_ass.php', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Welfare of Differently Abled Persons', 'Provide marriage-related assistance to eligible persons with disabilities and qualifying couples.', '["The couple must fall in a recognised category, e.g. a person without disability marrying a visually impaired / orthopaedically differently abled / speech and hearing impaired person, or two differently abled persons.", "Both partners must be above 18 years.", "A prescribed application form is available at the District Differently Abled Welfare Office."]'::jsonb, '[]'::jsonb, '["Obtain the prescribed application form from the District Differently Abled Welfare Office.", "Submit it with the required certificates to the District Differently Abled Welfare Officer.", "Grievances: Assistant Director (DAW), Commissionerate for Welfare of the Differently Abled, No.5 Kamarajar Salai, Chennai 600 005 (044-28444940)."]'::jsonb, NULL, '[{"url": "https://www.scd.tn.gov.in/marg_ass.php", "label": "Commissionerate for Welfare of the Differently Abled - Marriage assistance"}]'::jsonb, '2026-10-20', 'Amounts, eligibility, certificates and the application route were read on the official page on 2026-10-20.', '{"benefit": {"url": "https://www.scd.tn.gov.in/marg_ass.php", "confirmed": true, "checked_on": "2026-10-20", "what": "Rs.25,000 / Rs.50,000 + 8 g gold coin"}, "eligibility": {"url": "https://www.scd.tn.gov.in/marg_ass.php", "confirmed": true, "checked_on": "2026-10-20", "what": "category + age above 18"}, "documents": {"url": "https://www.scd.tn.gov.in/marg_ass.php", "confirmed": true, "checked_on": "2026-10-20", "what": "certificates to be furnished"}, "application": {"url": "https://www.scd.tn.gov.in/marg_ass.php", "confirmed": true, "checked_on": "2026-10-20", "what": "District Differently Abled Welfare Officer"}}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
INSERT INTO schemes.benefit (scheme_id, benefit_type, description, amount, currency, frequency, conditions, amount_status) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-MARRIAGE-DIFF-ABLED'), 'cash_transfer', 'Standard category: Rs.12,500 as National Savings Certificate and Rs.12,500 as cash / cheque / demand draft, with a certificate of appreciation and an 8-gram gold coin.', 25000, 'INR', 'one_time', 'Per the Commissionerate for Welfare of the Differently Abled page (benefit from 23.05.2016).', 'verified_current');
