INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-MULBERRY-ASSISTANCE', 'High-Yielding Mulberry Plantation Assistance', 'அதிக மகசூல் தரும் மல்பெரி நடவு உதவி', 'Support farmers establishing productive mulberry plantations for sericulture.', 'Subsidy for planting high-yielding mulberry varieties on gardens that meet prescribed cultivation standards, supplying leaves for silkworm rearing.', 'பட்டுப்புழு வளர்ப்பிற்காக அதிக மகசூல் தரும் மல்பெரி நடவு செய்யும் விவசாயிகளுக்கு மானியம் வழங்கும் திட்டம்.', 'state', NULL, 'agriculture_support', '75% subsidy: Rs.10,500 per acre against a unit cost of Rs.14,000.', NULL, 'https://www.tnagrisnet.tn.gov.in/people_app/sericulture_schemes.html', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Sericulture, Tamil Nadu', 'Support farmers establishing productive mulberry plantations for sericulture.', '["Good irrigation facility.", "Has planted a high-yielding mulberry variety (V1, MR2, S series, G4 etc.).", "Has planted 5,000 saplings per acre (pro rata) using the paired-row system [(5+3) x 2].", "Plantation extent of at least 1.00 acre and at most 5.00 acres."]'::jsonb, '[]'::jsonb, '["Contact the local Sericulture Department office.", "Confirm the approved variety, area and current rate.", "Submit the application with the listed documents.", "Complete the field inspection and verification."]'::jsonb, NULL, '[{"url": "https://www.tnagrisnet.tn.gov.in/people_app/sericulture_schemes.html", "label": "TN AgriSnet - Sericulture schemes"}]'::jsonb, '2026-10-20', 'Subsidy, eligibility and documents were read on the official page on 2026-10-20.', '{"benefit": {"url": "https://www.tnagrisnet.tn.gov.in/people_app/sericulture_schemes.html", "confirmed": true, "checked_on": "2026-10-20", "what": "75% subsidy, Rs.10,500 per acre"}, "eligibility": {"url": "https://www.tnagrisnet.tn.gov.in/people_app/sericulture_schemes.html", "confirmed": true, "checked_on": "2026-10-20", "what": "5 criteria"}, "documents": {"url": "https://www.tnagrisnet.tn.gov.in/people_app/sericulture_schemes.html", "confirmed": true, "checked_on": "2026-10-20", "what": "7 documents"}}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
INSERT INTO schemes.benefit (scheme_id, benefit_type, description, amount, currency, frequency, conditions, amount_status) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-MULBERRY-ASSISTANCE'), 'subsidy', 'Subsidy of Rs.10,500 per acre on a unit cost of Rs.14,000 (75%).', 10500, 'INR', 'per_acre', 'Per the Sericulture schemes page (state schemes).', 'verified_current');
