INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-MUDHALVAR-MARUNDHAGAM', 'Mudhalvar Marundhagam', 'முதல்வர் மருந்தகம்', 'Expand access to affordable medicines through participating outlets and support eligible outlet applicants.', 'The initiative supports access to medicines through designated pharmacies. Buying medicine and applying to run an outlet are different processes: the professional documents below apply to outlet applicants, not ordinary customers.', 'மலிவு விலையில் மருந்துகள் கிடைக்க முதல்வர் மருந்தகங்களை அமைக்கும் திட்டம்; மருந்தகம் அமைக்க விண்ணப்பிப்பவர்களுக்கு தனி தகுதிகள் உள்ளன.', 'state', NULL, 'health', 'Access to medicines at participating outlets; opportunity for eligible entrepreneurs and cooperative societies to set up an outlet.', 'https://mudhalvarmarundhagam.tn.gov.in/', 'https://mudhalvarmarundhagam.tn.gov.in/instruction', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Cooperation / designated implementing government agencies', 'Expand access to affordable medicines through participating outlets and support eligible outlet applicants.', '["Entrepreneurs holding D.Pharm / B.Pharm can apply (official instructions).", "An applicant without the certificate must submit a consent letter from a person holding a D.Pharm / B.Pharm certificate.", "Cooperative societies with a drug licence are also eligible.", "A valid e-mail ID and mobile number are mandatory; applications are made only through the online portal."]'::jsonb, '[]'::jsonb, '["Open the official portal and read the instructions.", "Register with a valid e-mail ID and mobile number.", "Upload the professional, property and regulatory documents.", "Complete departmental scrutiny."]'::jsonb, NULL, '[{"url": "https://mudhalvarmarundhagam.tn.gov.in/instruction", "label": "Mudhalvar Marundhagam - instructions"}]'::jsonb, '2026-10-20', 'Eligibility and the online-only application rule were read on the official instructions page on 2026-10-20; the premises and licence documents are from the project reference.', '{"eligibility": {"url": "https://mudhalvarmarundhagam.tn.gov.in/instruction", "confirmed": true, "checked_on": "2026-10-20", "what": "D.Pharm/B.Pharm, consent letter, cooperative societies, e-mail and mobile mandatory"}, "application": {"url": "https://mudhalvarmarundhagam.tn.gov.in/instruction", "confirmed": true, "checked_on": "2026-10-20", "what": "online portal only"}}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
INSERT INTO schemes.benefit (scheme_id, benefit_type, description, amount, currency, frequency, conditions, amount_status) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-MUDHALVAR-MARUNDHAGAM'), 'service', 'Access to medicines at participating outlets; outlet-establishment opportunity for eligible applicants.', NULL, 'INR', NULL, NULL, 'not_applicable');
INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-MUDHALVAR-MARUNDHAGAM'), 'D.Pharm / B.Pharm certificate', FALSE, 'or the consent letter of a certificate holder', 'category_specific');
