INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-MUDHALVAR-MARUNDHAGAM'), 'Premises ownership proof, or owner NOC / rental agreement', FALSE, NULL, 'unverified');
INSERT INTO schemes.document_requirement (scheme_id, document_name, mandatory, description, requirement_level) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-MUDHALVAR-MARUNDHAGAM'), 'Drug licence or cooperative records', FALSE, 'for cooperative societies', 'category_specific');
INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-CMUPT', 'Chief Minister''s Uzhavar Pathukappu Thittam (CMUPT)', 'முதலமைச்சரின் உழவர் பாதுகாப்புத் திட்டம்', 'Provide social security and financial assistance to eligible agricultural labourers, farmers and dependants.', 'Offers several kinds of assistance, including education, marriage, funeral and incapacity-related assistance, to registered eligible members and their dependants.', 'விவசாயத் தொழிலாளர்கள் மற்றும் விவசாயிகளுக்கு கல்வி, திருமணம், இறுதிச் சடங்கு உள்ளிட்ட உதவிகளை வழங்கும் சமூகப் பாதுகாப்புத் திட்டம்.', 'state', 1, 'social_security', 'Education, marriage, funeral and incapacity assistance; amounts vary by category and are not confirmed.', NULL, 'https://www.tnesevai.tn.gov.in/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_REVENUE'), 'Revenue Administration and Disaster Management', 'Provide social security and financial assistance to eligible agricultural labourers, farmers and dependants.', '["Eligible agricultural labourers and small / marginal farmers, including qualifying tenant cultivators.", "Reported landholding limits: wetland up to 2.50 acres or dryland up to 5 acres for the relevant farmer categories (project reference).", "Main members generally register at ages 18-65; verify current rules."]'::jsonb, '[]'::jsonb, '["Contact the Taluk Office, Special Tahsildar (Social Security Scheme) or Revenue Administration office.", "Confirm membership and select the assistance category.", "Submit documents and complete verification."]'::jsonb, NULL, '[{"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "label": "e-Sevai Service List: CMUPT, row 87"}]'::jsonb, '2026-10-20', 'Document list is from the official e-Sevai service list (row 87); eligibility limits and amounts are provisional.', '{"documents": {"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "confirmed": true, "checked_on": "2026-10-20", "what": "e-Sevai list row 87"}}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
