INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-INNUYIR-KAPPOM', 'Innuyir Kappom - Nammai Kaakkum 48', 'இன்னுயிர் காப்போம் - நம்மைக் காக்கும் 48', 'Provide prompt emergency treatment to eligible road-accident victims during the first 48 hours.', 'Supports emergency care at participating hospitals. Treatment should never be delayed while documents are collected.', 'சாலை விபத்தில் காயமடைந்தவர்களுக்கு முதல் 48 மணி நேரம் பங்கேற்கும் மருத்துவமனைகளில் அவசர சிகிச்சை வழங்கும் திட்டம்.', 'state', 2, 'health', 'Emergency cashless treatment in the first 48 hours; the cashless ceiling (reported as increased from Rs.1 lakh to Rs.2 lakh) is not confirmed.', NULL, 'https://tnhsp.org/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Health and Family Welfare / Tamil Nadu Health Systems Project', 'Provide prompt emergency treatment to eligible road-accident victims during the first 48 hours.', '["Road-accident victims in Tamil Nadu meeting current programme conditions.", "Treatment must be within the approved emergency-care scope at a participating hospital."]'::jsonb, '[]'::jsonb, '["Take the patient to an appropriate emergency department or call emergency services.", "Tell the hospital the injury resulted from a road accident.", "Ask whether the hospital participates and follow its scheme-processing instructions."]'::jsonb, NULL, '[{"url": "https://tnhsp.org/", "label": "Tamil Nadu Health Systems Project"}]'::jsonb, '2026-10-20', 'The Rs.2 lakh ceiling is unconfirmed.', '{}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
INSERT INTO schemes.benefit (scheme_id, benefit_type, description, amount, currency, frequency, conditions, amount_status) VALUES ((SELECT scheme_id FROM schemes.scheme WHERE scheme_code = 'TN-INNUYIR-KAPPOM'), 'cashless_treatment', 'Emergency cashless treatment during the first 48 hours.', 200000, 'INR', 'per_case', 'The project reference cites a December 2024 order raising the ceiling to Rs.2 lakh; a news item only said it would be raised ''soon'', and no order was found.', 'unverified');
