INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-DWPS', 'Destitute Widow Pension Scheme (DWPS)', 'ஆதரவற்ற விதவை ஓய்வூதியத் திட்டம்', 'Provide recurring financial assistance to eligible widows facing financial hardship.', 'A social-security pension for eligible widows after verification by the competent Revenue Administration authority.', 'பொருளாதார நெருக்கடியில் உள்ள தகுதியுள்ள விதவைகளுக்கு மாதாந்திர ஓய்வூதியம் வழங்கும் திட்டம்.', 'state', 1, 'social_security', 'Monthly pension; Rs.1,200 was listed on the Revenue Administration table as of March 2024.', 'https://oap.tn.gov.in/', 'https://oap.tn.gov.in/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_REVENUE'), 'Revenue Administration and Disaster Management', 'Provide recurring financial assistance to eligible widows facing financial hardship.', '["Applicant is a widow meeting destitution and residence requirements.", "Published information lists a minimum age of 18 and a fixed-assets limit of Rs.1 lakh; confirm current rules and exceptions."]'::jsonb, '[]'::jsonb, '["Contact the Taluk Office or an authorised e-Sevai centre.", "Submit the prescribed application and widow-status records.", "Complete financial and eligibility verification and track the status."]'::jsonb, NULL, '[{"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "label": "e-Sevai Service List: DWPS, row 84"}, {"url": "https://oap.tn.gov.in/", "label": "Social security pensions portal"}]'::jsonb, '2026-10-20', 'Document list is from the official e-Sevai service list (row 84).', '{"documents": {"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "confirmed": true, "checked_on": "2026-10-20", "what": "e-Sevai list row 84"}}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
