INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-MUTHULAKSHMI-MATERNITY', 'Dr. Muthulakshmi Reddy Maternity Benefit Scheme', 'டாக்டர் முத்துலட்சுமி ரெட்டி மகப்பேறு நிதியுதவித் திட்டம்', 'Provide financial and nutritional support to eligible pregnant women.', 'Beneficiaries are registered through the public maternal-health system and receive assistance according to the current instalment and nutrition-support rules.', 'தகுதியுள்ள கர்ப்பிணிப் பெண்களுக்கு நிதி மற்றும் ஊட்டச்சத்து உதவி வழங்கும் மகப்பேறு நிதியுதவித் திட்டம்.', 'state', 2, 'maternal_child_health', 'Maternity financial assistance and nutritional support; amounts are not confirmed.', NULL, 'https://www.tnhealth.tn.gov.in', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Health and Family Welfare', 'Provide financial and nutritional support to eligible pregnant women.', '["Pregnant women meeting current income, family and residence conditions.", "District guidance describes support for the first two deliveries; verify the current order.", "Pregnancy must be registered through the public-health system."]'::jsonb, '[]'::jsonb, '["Register the pregnancy through the Village Health Nurse or Urban Health Nurse.", "Obtain the PICME / RCH number and provide bank details.", "Attend the required antenatal visits and follow the health worker''s guidance for instalments."]'::jsonb, NULL, '[]'::jsonb, '2026-10-20', 'No official scheme page was confirmed; amounts are not stated.', '{}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
