INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-MAGAPERU-SANJEEVI', 'Amma Magaperu Sanjeevi Kit', 'அம்மா மகப்பேறு சஞ்சீவி பெட்டகம்', 'Provide specified maternal-care or newborn-care supplies through participating public-health facilities.', 'Listed among maternal and child welfare services. Current distribution, kit contents and the relationship to other baby-care programmes require confirmation.', 'பொது சுகாதார நிலையங்கள் மூலம் தாய் மற்றும் சேய் பராமரிப்புப் பொருட்களை வழங்கும் திட்டம் (தற்போதைய நிலை உறுதிப்படுத்தப்படவில்லை).', 'state', 2, 'maternal_child_health', 'Maternal-care or newborn-care supplies; contents and operational status are not confirmed.', NULL, 'https://www.tnhealth.tn.gov.in', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Health and Family Welfare', 'Provide specified maternal-care or newborn-care supplies through participating public-health facilities.', '["Pregnant women or mothers covered by the applicable programme.", "Registration through the relevant public-health facility may be required."]'::jsonb, '[]'::jsonb, '["Ask the Village Health Nurse, Urban Health Nurse or government maternity facility whether the kit is currently distributed.", "Follow the facility''s collection instructions."]'::jsonb, NULL, '[]'::jsonb, '2026-10-20', 'Operational status unconfirmed.', '{}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_su