INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-SEWING-MACHINE', 'Sathiyavani Muthu Ammaiyar Free Sewing Machine Scheme', 'சத்தியவாணி முத்து அம்மையார் நினைவு இலவச தையல் இயந்திரத் திட்டம்', 'Support disadvantaged beneficiaries in developing tailoring skills and self-employment.', 'Provides sewing machines to eligible beneficiary categories under current department rules.', 'தகுதியுள்ள பயனாளிகளுக்கு இலவச தையல் இயந்திரம் வழங்கி சுயதொழிலுக்கு உதவும் திட்டம்.', 'state', 5, 'livelihood', 'Free sewing machine for eligible beneficiaries.', NULL, 'https://www.tnesevai.tn.gov.in/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_WELFARE'), 'Social Welfare and Women Empowerment', 'Support disadvantaged beneficiaries in developing tailoring skills and self-employment.', '["Eligible widows, deserted women, poor women, persons with disabilities and other categories in current guidelines.", "Income, residence and tailoring-related requirements may apply."]'::jsonb, '[]'::jsonb, '["Contact the District Social Welfare Office or an authorised e-Sevai centre.", "Confirm current eligibility and whether applications are open.", "Submit the prescribed application and documents for verification."]'::jsonb, NULL, '[{"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "label": "e-Sevai Service List: SWL-101 listed"}]'::jsonb, '2026-10-20', 'Listed as SWL-101; no fee or document list is given there.', '{"listed": {"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "confirmed": true, "checked_on": "2026-10-20", "what": "SWL-101 listed"}}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
