INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-WIDOW-REMARRIAGE', 'Dr. Dharmambal Ammaiyar Ninaivu Widow Remarriage Assistance Scheme', 'டாக்டர் தர்மாம்பாள் அம்மையார் நினைவு விதவை மறுமண நிதியுதவித் திட்டம்', 'Encourage eligible widow remarriage and support qualifying couples.', 'Historical descriptions list financial and gold-coin assistance. Current operational status and benefit categories require confirmation.', 'விதவை மறுமணத்தை ஊக்குவிக்க தம்பதியருக்கு நிதி மற்றும் தங்க நாணயம் வழங்கும் திட்டம் (தற்போதைய நிலை உறுதிப்படுத்தப்படவில்லை).', 'state', 5, 'marriage_assistance', 'Historical amounts only; current availability not confirmed.', NULL, 'https://www.tnesevai.tn.gov.in/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_WELFARE'), 'Social Welfare and Women Empowerment', 'Encourage eligible widow remarriage and support qualifying couples.', '["Bride qualifies as a widow under the applicable rules.", "Marriage, age, residence and other prescribed requirements.", "Educational qualification may decide the category."]'::jsonb, '[]'::jsonb, '["Contact the District Social Welfare Office or an authorised e-Sevai centre.", "Confirm the current category and benefit schedule.", "Submit documents and complete verification."]'::jsonb, NULL, '[{"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "label": "e-Sevai Service List: SWL-105 listed"}]'::jsonb, '2026-10-20', 'Listed as SWL-105; amounts historical.', '{"listed": {"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "confirmed": true, "checked_on": "2026-10-20", "what": "SWL-105 listed"}}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
