INSERT INTO schemes.scheme (scheme_code, scheme_name, name_ta, short_description, full_description, short_description_ta, scheme_level, department_id, category, benefits_summary, application_url, official_url, status, verification_status, source_id, implementing_department, purpose, eligibility_points, exclusion_points, application_steps, how_to_apply_note, source_urls, last_checked_on, content_notes, field_evidence) VALUES ('TN-INTERCASTE-MARRIAGE', 'Dr. Muthulakshmi Reddy Ninaivu Inter-Caste Marriage Assistance Scheme', 'டாக்டர் முத்துலட்சுமி ரெட்டி நினைவு சாதி கடந்த திருமண நிதியுதவித் திட்டம்', 'Support eligible inter-caste couples and promote social equality.', 'Has historically provided marriage assistance for couples in prescribed inter-caste categories.', 'சாதி கடந்த திருமணம் செய்யும் தம்பதியருக்கு நிதி மற்றும் தங்க நாணயம் வழங்கும் திட்டம்.', 'state', 5, 'marriage_assistance', 'Historical amounts only; current rules must be verified.', NULL, 'https://www.tnesevai.tn.gov.in/', 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_WELFARE'), 'Social Welfare and Women Empowerment', 'Support eligible inter-caste couples and promote social equality.', '["Marriage falls within a recognised scheme category.", "Both spouses meet age, marriage, residence and documentation requirements.", "Community categories and educational criteria must be confirmed from current guidelines."]'::jsonb, '[]'::jsonb, '["Contact the District Social Welfare Office or an authorised e-Sevai centre.", "Confirm the category and current benefit structure.", "Submit the prescribed application and complete verification."]'::jsonb, NULL, '[{"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "label": "e-Sevai Service List: SWL-106 listed"}]'::jsonb, '2026-10-20', 'Listed as SWL-106; amounts historical.', '{"listed": {"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "confirmed": true, "checked_on": "2026-10-20", "what": "SWL-106 listed"}}'::jsonb) ON CONFLICT (scheme_code) DO UPDATE SET short_description = EXCLUDED.short_description, full_description = EXCLUDED.full_description, short_description_ta = EXCLUDED.short_description_ta, benefits_summary = EXCLUDED.benefits_summary, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, implementing_department = EXCLUDED.implementing_department, purpose = EXCLUDED.purpose, eligibility_points = EXCLUDED.eligibility_points, exclusion_points = EXCLUDED.exclusion_points, application_steps = EXCLUDED.application_steps, how_to_apply_note = EXCLUDED.how_to_apply_note, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, field_evidence = EXCLUDED.field_evidence;
