INSERT INTO services.service (service_code, service_name, name_ta, department_id, category, description, description_ta, application_url, official_url, government_fee, service_charge, processing_time, status, verification_status, source_id, responsible_department, eligibility_points, application_steps, how_to_apply, applicable_rules, source_urls, last_checked_on, content_notes, fee_note, processing_time_note, fee_status, field_evidence) VALUES ('SVC-PATTA-TRANSFER', 'Application for Patta Transfer (Mutation of Land)', 'பட்டா மாறுதல் விண்ணப்பம்', 1, 'land_record', 'Updates Tamil Nadu revenue records to show a new landholder after a sale, inheritance, gift, partition or another legally valid transfer. Subdivision may be needed when only part of a survey field is transferred.', 'விற்பனை, வாரிசு, தானம், பாகப்பிரிவினை போன்ற சட்டப்படியான மாற்றத்திற்குப் பிறகு நில வருவாய் பதிவேடுகளில் புதிய நில உரிமையாளரைப் பதிவு செய்யும் சேவை.', 'https://www.tnesevai.tn.gov.in/', 'https://www.tnesevai.tn.gov.in/', NULL, NULL, NULL, 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_REVENUE'), 'Revenue Administration / Tamil Nilam', '["Purchaser, legal heir, recipient of a valid transfer or another person entitled to request mutation under the land-revenue rules."]'::jsonb, '[]'::jsonb, 'Through the Tamil Nilam / e-Sevai route or the competent Taluk Revenue Office (route as described in the project reference; the e-Sevai list has no patta-transfer row, only ''CSS-701 Patta Appeal'').', NULL, '[{"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "label": "e-Sevai Service List (no patta-transfer row)"}]'::jsonb, '2026-10-20', 'No official fee, timeline or document list was found for this service.', NULL, 'Not confirmed from an official source.', 'not_listed', '{}'::jsonb) ON CONFLICT (service_code, department_id) DO UPDATE SET description = EXCLUDED.description, description_ta = EXCLUDED.description_ta, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, government_fee = EXCLUDED.government_fee, service_charge = EXCLUDED.service_charge, processing_time = EXCLUDED.processing_time, responsible_department = EXCLUDED.responsible_department, eligibility_points = EXCLUDED.eligibility_points, application_steps = EXCLUDED.application_steps, how_to_apply = EXCLUDED.how_to_apply, applicable_rules = EXCLUDED.applicable_rules, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, fee_note = EXCLUDED.fee_note, processing_time_note = EXCLUDED.processing_time_note, fee_status = EXCLUDED.fee_status, field_evidence = EXCLUDED.field_evidence;
