INSERT INTO services.service (service_code, service_name, name_ta, department_id, category, description, description_ta, application_url, official_url, government_fee, service_charge, processing_time, status, verification_status, source_id, responsible_department, eligibility_points, application_steps, how_to_apply, applicable_rules, source_urls, last_checked_on, content_notes, fee_note, processing_time_note, fee_status, field_evidence) VALUES ('SVC-DEATH-CERT', 'Death Certificate Issuance', 'இறப்பு சான்றிதழ் நகல் பெற', 7, 'vital_statistics', 'An official record of a person''s death, commonly used for inheritance, pension claims, insurance, bank procedures and updating official records.', 'ஒருவரின் இறப்பு குறித்த அதிகாரப்பூர்வ பதிவு; வாரிசுரிமை, ஓய்வூதியம், காப்பீடு போன்றவற்றுக்கு பயன்படுகிறது.', 'https://www.crstn.org', 'https://www.crstn.org', NULL, NULL, NULL, 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Local birth and death registration authority', '["An eligible family member, legal representative or other authorised person, subject to access rules."]'::jsonb, '["Open the e-Sevai portal or visit an e-Sevai centre.", "Choose the service and give the details requested.", "Upload or hand over the documents shown on this page.", "Pay any fee shown on the payment screen and keep the acknowledgement."]'::jsonb, 'Printing of a registered death certificate is on the e-Sevai list (Directorate of Public Health; Greater Chennai Corporation). Registration is with the registrar of the place of death.', NULL, '[{"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "label": "e-Sevai Service List: rows 45 and 51"}]'::jsonb, '2026-10-20', NULL, 'The e-Sevai list shows no application fee and a service charge of Rs.100 for printing a death certificate (Directorate of Public Health) and Rs.40 (Greater Chennai Corporation).', 'Not confirmed from an official source.', 'listed_official_2023', '{"fee": {"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "confirmed": true, "checked_on": "2026-10-20", "what": "e-Sevai list row 45"}}'::jsonb) ON CONFLICT (service_code, department_id) DO UPDATE SET description = EXCLUDED.description, description_ta = EXCLUDED.description_ta, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, government_fee = EXCLUDED.government_fee, service_charge = EXCLUDED.service_charge, processing_time = EXCLUDED.processing_time, responsible_department = EXCLUDED.responsible_department, eligibility_points = EXCLUDED.eligibility_points, application_steps = EXCLUDED.application_steps, how_to_apply = EXCLUDED.how_to_apply, applicable_rules = EXCLUDED.applicable_rules, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, fee_note = EXCLUDED.fee_note, processing_time_note = EXCLUDED.processing_time_note, fee_status = EXCLUDED.fee_status, field_evidence = EXCLUDED.field_evidence;
