INSERT INTO services.service (service_code, service_name, name_ta, department_id, category, description, description_ta, application_url, official_url, government_fee, service_charge, processing_time, status, verification_status, source_id, responsible_department, eligibility_points, application_steps, how_to_apply, applicable_rules, source_urls, last_checked_on, content_notes, fee_note, processing_time_note, fee_status, field_evidence) VALUES ('SVC-ENCUMB-CERT', 'Encumbrance Certificate (EC)', 'வில்லங்கச் சான்றிதழ்', 16, 'land_record', 'A search record of registered transactions affecting a property over a period. Used in property purchases, loans and title checks. An EC is not conclusive proof of ownership or that every possible claim is absent.', 'ஒரு சொத்தின் மீது குறிப்பிட்ட காலத்தில் பதிவு செய்யப்பட்ட பரிவர்த்தனைகளின் தேடல் பதிவு; இது உரிமையின் முடிவான சான்று அல்ல.', 'https://www.tnreginet.gov.in/portal/', 'https://www.tnreginet.gov.in/portal/', NULL, NULL, NULL, 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Commercial Taxes and Registration Department / Inspector General of Registration', '["A person seeking registered transaction information for a property, subject to portal requirements."]'::jsonb, '["Open the e-Sevai portal or visit an e-Sevai centre.", "Choose the service and give the details requested.", "Upload or hand over the documents shown on this page.", "Pay any fee shown on the payment screen and keep the acknowledgement."]'::jsonb, 'Online through the TNREGINET registration portal; EC issuance and EC download are also listed on the e-Sevai list.', 'Registration Act, 1908 (search of records).', '[{"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "label": "e-Sevai Service List: rows 56 and 58"}, {"url": "https://www.tnreginet.gov.in/portal/", "label": "TNREGINET (returned a server error on 2026-10-20)"}]'::jsonb, '2026-10-20', NULL, 'The e-Sevai list shows no application fee and a service charge of Rs.10 for issuance of an EC and Rs.2 for EC download. Statutory search fees on TNREGINET are not listed there.', 'Not confirmed from an official source.', 'listed_official_2023', '{"fee": {"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "confirmed": true, "checked_on": "2026-10-20", "what": "e-Sevai list row 56"}}'::jsonb) ON CONFLICT (service_code, department_id) DO UPDATE SET description = EXCLUDED.description, description_ta = EXCLUDED.description_ta, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, government_fee = EXCLUDED.government_fee, service_charge = EXCLUDED.service_charge, processing_time = EXCLUDED.processing_time, responsible_department = EXCLUDED.responsible_department, eligibility_points = EXCLUDED.eligibility_points, application_steps = EXCLUDED.application_steps, how_to_apply = EXCLUDED.how_to_apply, applicable_rules = EXCLUDED.applicable_rules, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, fee_note = EXCLUDED.fee_note, processing_time_note = EXCLUDED.processing_time_note, fee_status = EXCLUDED.fee_status, field_evidence = EXCLUDED.field_evidence;
