INSERT INTO services.service (service_code, service_name, name_ta, department_id, category, description, description_ta, application_url, official_url, government_fee, service_charge, processing_time, status, verification_status, source_id, responsible_department, eligibility_points, application_steps, how_to_apply, applicable_rules, source_urls, last_checked_on, content_notes, fee_note, processing_time_note, fee_status, field_evidence) VALUES ('SVC-LEGAL-HEIR', 'Legal Heir Certificate', 'வாரிசு சான்றிதழ்', 1, 'certificate', 'Records the recognised legal heirs of a deceased person for administrative purposes such as pension processing and service benefits. It does not replace probate, succession proceedings or other legal instruments where required.', 'இறந்தவரின் சட்டப்படியான வாரிசுகளை நிர்வாகத் தேவைகளுக்காக பதிவு செய்யும் சான்றிதழ்.', 'https://www.tnesevai.tn.gov.in/', 'https://www.tnesevai.tn.gov.in/', 0.0, 60.0, NULL, 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_REVENUE'), 'Revenue Administration', '["An eligible family member or other person entitled to request certification of the deceased person''s legal heirs."]'::jsonb, '["Open the e-Sevai portal or visit an e-Sevai centre.", "Choose the service and give the details requested.", "Upload or hand over the documents shown on this page.", "Pay any fee shown on the payment screen and keep the acknowledgement."]'::jsonb, 'Apply at an e-Sevai centre: the official list shows this service as operator-assisted. The list''s link for applying is the e-Sevai portal.', NULL, '[{"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "label": "e-Sevai Service List: row 73"}]'::jsonb, '2026-10-20', NULL, 'Per the official e-Sevai service list (last updated 10 Apr 2023): application fee Rs.0, e-Sevai service-centre charge Rs.60. This list is more than three years old - confirm on the live portal or payment screen.', 'Not confirmed from an official source.', 'listed_official_2023', '{"fee": {"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "confirmed": true, "checked_on": "2026-10-20", "what": "e-Sevai list row 73"}, "documents": {"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "confirmed": true, "checked_on": "2026-10-20", "what": "e-Sevai list row 73"}}'::jsonb) ON CONFLICT (service_code, department_id) DO UPDATE SET description = EXCLUDED.description, description_ta = EXCLUDED.description_ta, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, government_fee = EXCLUDED.government_fee, service_charge = EXCLUDED.service_charge, processing_time = EXCLUDED.processing_time, responsible_department = EXCLUDED.responsible_department, eligibility_points = EXCLUDED.eligibility_points, application_steps = EXCLUDED.application_steps, how_to_apply = EXCLUDED.how_to_apply, applicable_rules = EXCLUDED.applicable_rules, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, fee_note = EXCLUDED.fee_note, processing_time_note = EXCLUDED.processing_time_note, fee_status = EXCLUDED.fee_status, field_evidence = EXCLUDED.field_evidence;
