INSERT INTO services.service (service_code, service_name, name_ta, department_id, category, description, description_ta, application_url, official_url, government_fee, service_charge, processing_time, status, verification_status, source_id, responsible_department, eligibility_points, application_steps, how_to_apply, applicable_rules, source_urls, last_checked_on, content_notes, fee_note, processing_time_note, fee_status, field_evidence) VALUES ('SVC-RATION-SMART', 'Smart Ration Card Application', 'புதிய மின்னணு குடும்ப அட்டை', 17, 'civil_supplies', 'Lets an eligible household apply for a new electronic family card or request a household change, such as a split after marriage. Access to Public Distribution System benefits depends on household eligibility and rules.', 'தகுதியுள்ள குடும்பம் புதிய மின்னணு குடும்ப அட்டைக்கு அல்லது குடும்ப மாற்றத்திற்கு விண்ணப்பிக்கும் சேவை.', 'https://www.tnpds.gov.in/', 'https://www.tnpds.gov.in/', 0.0, 60.0, NULL, 'active', 'provisional', (SELECT source_id FROM system.source_registry WHERE source_code = 'TN_GOV_PORTAL'), 'Food, Civil Supplies and Consumer Protection', '["Households satisfying the current requirements for a new family card or the relevant change to an existing card."]'::jsonb, '["Open the e-Sevai portal or visit an e-Sevai centre.", "Choose the service and give the details requested.", "Upload or hand over the documents shown on this page.", "Pay any fee shown on the payment screen and keep the acknowledgement."]'::jsonb, 'Through the Tamil Nadu Public Distribution System portal; ''Application for New Ration Card'' is also listed on the e-Sevai list.', NULL, '[{"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "label": "e-Sevai Service List: row 9"}, {"url": "https://www.tnpds.gov.in/", "label": "TN Public Distribution System"}]'::jsonb, '2026-10-20', NULL, 'Per the official e-Sevai service list (last updated 10 Apr 2023): application fee Rs.0, e-Sevai service-centre charge Rs.60. This list is more than three years old - confirm on the live portal or payment screen.', 'Not confirmed from an official source.', 'listed_official_2023', '{"fee": {"url": "https://www.tnesevai.tn.gov.in/Pages/ServiceList.aspx", "confirmed": true, "checked_on": "2026-10-20", "what": "e-Sevai list row 9"}}'::jsonb) ON CONFLICT (service_code, department_id) DO UPDATE SET description = EXCLUDED.description, description_ta = EXCLUDED.description_ta, application_url = EXCLUDED.application_url, official_url = EXCLUDED.official_url, government_fee = EXCLUDED.government_fee, service_charge = EXCLUDED.service_charge, processing_time = EXCLUDED.processing_time, responsible_department = EXCLUDED.responsible_department, eligibility_points = EXCLUDED.eligibility_points, application_steps = EXCLUDED.application_steps, how_to_apply = EXCLUDED.how_to_apply, applicable_rules = EXCLUDED.applicable_rules, source_urls = EXCLUDED.source_urls, last_checked_on = EXCLUDED.last_checked_on, content_notes = EXCLUDED.content_notes, fee_note = EXCLUDED.fee_note, processing_time_note = EXCLUDED.processing_time_note, fee_status = EXCLUDED.fee_status, field_evidence = EXCLUDED.field_evidence;
